// Package goldenticket is a 1/1 GRC721 NFT: one golden ticket, minted to the
// publisher when the package is added. It exists to check that a gno.land
// collection shows in the Adena wallet before gnofly's planes go to mainnet,
// so it is built the way the planes are:
//
//   - the collection is a gno.land/p/nt/grc721/v0 token made with NewToken,
//     whose NewToken and Transfer events Adena finds on its indexer;
//   - the read functions take a grc721.TokenID and return (value, error), as
//     Adena calls them: OwnerOf("1"), BalanceOf("g1..."), TokenURI("1") as
//     the <img src>, TokenMetadata("1") as JSON with camelCase traitType.
//
// Transfer moves the ticket, so it can reach any Adena account.
package goldenticket

import (
	"errors"
	"strings"

	"gno.land/p/nt/grc721/v0"
)

const (
	tokenName   = "Golden Ticket"
	tokenSymbol = "GOLD"
	ticket      = grc721.TokenID("1")

	// An https PNG, as the planes' images are: the SuperGnome of gnofly, from
	// the Blob store that serves the collection. Adena loads https: and data:
	// images only.
	image = "https://xjfvwq1pdzcznycc.public.blob.vercel-storage.com/planes/777.png"

	errNoTicket = "goldenticket: there is one ticket, id 1"
	errNotOwner = "goldenticket: caller does not hold the ticket"
	errBadOwner = "goldenticket: invalid recipient address"
)

var (
	// Token is the collection, read-only: Token.OwnerOf("1"), Token.BalanceOf.
	Token  *grc721.Token
	ledger *grc721.PrivateLedger
)

// init runs once, when the package is added to the chain. This is the only
// moment cur.Previous() is the publisher, who receives the ticket.
//
// Under `gno test` there is no publisher and the address is empty. The tests
// call bootstrap themselves with a real address.
func init(cur realm) {
	bootstrap(cur.Previous().Address(), cur)
}

// bootstrap creates the collection and mints the ticket to holder; with no
// valid holder, under `gno test`, it mints nothing.
func bootstrap(holder address, rlm realm) {
	Token, ledger = grc721.NewToken(tokenName, tokenSymbol, 0, rlm)
	if !holder.IsValid() {
		return
	}
	if err := ledger.Mint(holder, ticket); err != nil {
		panic(err)
	}
}

// Name and Symbol, as GRC721 tokens have them. Adena reads both from the
// NewToken event.
func Name() string   { return tokenName }
func Symbol() string { return tokenSymbol }

// OwnerOf returns who holds the ticket, or an error for any other id.
func OwnerOf(tid grc721.TokenID) (address, error) {
	if tid != ticket {
		return "", errors.New(errNoTicket)
	}
	return Token.OwnerOf(tid)
}

// BalanceOf returns 1 for the holder of the ticket, 0 for everyone else.
func BalanceOf(addr address) (int64, error) {
	return Token.BalanceOf(addr)
}

// TokenURI returns the image of the ticket: what Adena shows.
func TokenURI(tid grc721.TokenID) (string, error) {
	if _, err := OwnerOf(tid); err != nil {
		return "", err
	}
	return image, nil
}

// TokenMetadata returns the metadata of the ticket as JSON, with the keys
// Adena reads.
func TokenMetadata(tid grc721.TokenID) (string, error) {
	if _, err := OwnerOf(tid); err != nil {
		return "", err
	}
	return `{"name":"` + tokenName + ` #1","description":"A 1/1 on gno.land, minted to check that collections show in Adena.",` +
		`"image":"` + image + `","attributes":[{"traitType":"edition","value":"1 of 1"},{"traitType":"metal","value":"gold"}]}`, nil
}

// Transfer gives the ticket to someone else. Only its holder can, by a
// direct call (maketx call or Adena), not through another realm.
func Transfer(cur realm, to address) {
	caller := cur.Previous()
	if !caller.IsUserCall() {
		panic(errNotOwner)
	}
	if !to.IsValid() {
		panic(errBadOwner)
	}
	holder, err := Token.OwnerOf(ticket)
	if err != nil || holder != caller.Address() {
		panic(errNotOwner)
	}
	if err := ledger.TransferFrom(holder, holder, to, ticket); err != nil {
		panic(err)
	}
}

// Render shows the ticket and who holds it.
func Render(_ string) string {
	var b strings.Builder
	b.WriteString("# " + tokenName + "\n\n")
	b.WriteString("A 1/1 GRC721 on gno.land, minted to check that collections show in Adena.\n\n")
	b.WriteString("![" + tokenName + "](" + image + ")\n\n")
	holder, err := Token.OwnerOf(ticket)
	if err != nil {
		b.WriteString("Not minted.\n")
		return b.String()
	}
	b.WriteString("Held by `" + holder.String() + "`.\n")
	return b.String()
}

package goldenticket

import (
	"strings"
	"testing"

	"gno.land/p/nt/grc721/v0"
	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
)

var (
	aliceAddr = testutils.TestAddress("alice")
	bobAddr   = testutils.TestAddress("bob")
)

// reset redoes what init does on chain, with alice as the publisher.
func reset(cur realm) {
	func(cur realm) {
		bootstrap(aliceAddr, cur)
	}(cross(cur))
}

// The reads, called as Adena calls them: the id a quoted string, two values.
func TestReads(cur realm, t *testing.T) {
	reset(cur)

	owner, err := OwnerOf("1")
	uassert.NoError(t, err)
	uassert.Equal(t, aliceAddr, owner)

	n, err := BalanceOf(aliceAddr)
	uassert.NoError(t, err)
	uassert.Equal(t, int64(1), n)
	n, err = BalanceOf(bobAddr)
	uassert.NoError(t, err)
	uassert.Equal(t, int64(0), n)

	uri, err := TokenURI("1")
	uassert.NoError(t, err)
	uassert.Equal(t, image, uri)
	uassert.True(t, strings.HasPrefix(uri, "https://"))

	meta, err := TokenMetadata("1")
	uassert.NoError(t, err)
	uassert.Equal(t, `{"name":"Golden Ticket #1","description":"A 1/1 on gno.land, minted to check that collections show in Adena.",`+
		`"image":"`+image+`","attributes":[{"traitType":"edition","value":"1 of 1"},{"traitType":"metal","value":"gold"}]}`, meta)

	uassert.Equal(t, int64(1), Token.TotalSupply())
	uassert.Equal(t, "Golden Ticket", Name())
	uassert.Equal(t, "GOLD", Symbol())

	// Any other id is an error, not a panic.
	for _, bad := range []grc721.TokenID{"", "0", "2", "01", " 1"} {
		_, err = OwnerOf(bad)
		uassert.ErrorContains(t, err, errNoTicket, string(bad))
		_, err = TokenURI(bad)
		uassert.ErrorContains(t, err, errNoTicket, string(bad))
		_, err = TokenMetadata(bad)
		uassert.ErrorContains(t, err, errNoTicket, string(bad))
	}
}

func TestTransfer(cur realm, t *testing.T) {
	reset(cur)

	// Only the holder moves the ticket.
	testing.SetRealm(testing.NewUserRealm(bobAddr))
	uassert.AbortsWithMessage(t, cur, errNotOwner, func() {
		Transfer(cross(cur), bobAddr)
	})

	testing.SetRealm(testing.NewUserRealm(aliceAddr))
	uassert.AbortsWithMessage(t, cur, errBadOwner, func() {
		Transfer(cross(cur), address("nope"))
	})
	Transfer(cross(cur), bobAddr)
	owner, err := OwnerOf("1")
	uassert.NoError(t, err)
	uassert.Equal(t, bobAddr, owner)
	n, _ := BalanceOf(aliceAddr)
	uassert.Equal(t, int64(0), n)
	n, _ = BalanceOf(bobAddr)
	uassert.Equal(t, int64(1), n)

	// Not through another realm.
	testing.SetRealm(testing.NewCodeRealm("gno.land/r/demo/relay"))
	uassert.AbortsWithMessage(t, cur, errNotOwner, func() {
		Transfer(cross(cur), aliceAddr)
	})
}

func TestRender(cur realm, t *testing.T) {
	reset(cur)
	out := Render("")
	uassert.True(t, strings.Contains(out, "# Golden Ticket\n"))
	uassert.True(t, strings.Contains(out, "!["+tokenName+"]("+image+")"))
	uassert.True(t, strings.Contains(out, "Held by `"+aliceAddr.String()+"`."))
}

// Package goldenticket is a 1/1 GRC721 NFT: one golden ticket, minted to the
// publisher when the package is added. It checks that a gno.land collection
// shows in the Adena wallet, built the way gnofly's planes are:
//
//   - the collection is a gno.land/p/nt/grc721/v0 token made with NewToken,
//     whose NewToken and Transfer events Adena finds on its indexer;
//   - the read functions take a grc721.TokenID and return (value, error), as
//     Adena calls them: OwnerOf("1"), BalanceOf("g1..."), TokenURI("1") as
//     the <img src>, TokenMetadata("1") as JSON with camelCase traitType.
//
// v2 of goldenticket: the image is no longer a constant. The publisher is
// the admin and moves it with SetImage, as the planes' SetImageBase does, so
// it can live where both Adena (any https: image) and gno.land's pages (an
// allowlist: GitHub, imgur, IPFS) load it.
//
// Transfer moves the ticket, so it can reach any Adena account.
package goldenticket

import (
	"errors"
	"strings"

	"gno.land/p/nt/grc721/v0"
)

const (
	tokenName   = "Golden Ticket"
	tokenSymbol = "GOLD"
	ticket      = grc721.TokenID("1")

	// The gno icon from gnolang/workshops, served by raw.githubusercontent.com:
	// gno.land's content policy allows *.githubusercontent.com images.
	defaultImage = "https://raw.githubusercontent.com/gnolang/workshops/main/assets/gno-icon-white.png"

	errNoTicket = "goldenticket: there is one ticket, id 1"
	errNotOwner = "goldenticket: caller does not hold the ticket"
	errBadOwner = "goldenticket: invalid recipient address"
	errNotAdmin = "goldenticket: caller is not the admin"
	errBadImage = "goldenticket: image must be an https URL, 12 to 300 characters of [A-Za-z0-9./_-:?=&%~+]"
)

var (
	// Token is the collection, read-only: Token.OwnerOf("1"), Token.BalanceOf.
	Token  *grc721.Token
	ledger *grc721.PrivateLedger

	admin address // the publisher: the only one who sets the image
	image string  // what TokenURI returns, and Render and TokenMetadata show
)

// init runs once, when the package is added to the chain. This is the only
// moment cur.Previous() is the publisher, who receives the ticket and is the
// admin.
//
// Under `gno test` there is no publisher and the address is empty. The tests
// call bootstrap themselves with a real address.
func init(cur realm) {
	bootstrap(cur.Previous().Address(), cur)
}

// bootstrap creates the collection and mints the ticket to publisher; with
// no valid publisher, under `gno test`, it mints nothing.
func bootstrap(publisher address, rlm realm) {
	Token, ledger = grc721.NewToken(tokenName, tokenSymbol, 0, rlm)
	admin = publisher
	image = defaultImage
	if !publisher.IsValid() {
		return
	}
	if err := ledger.Mint(publisher, ticket); err != nil {
		panic(err)
	}
}

// Name and Symbol, as GRC721 tokens have them. Adena reads both from the
// NewToken event.
func Name() string   { return tokenName }
func Symbol() string { return tokenSymbol }

// Admin returns who may set the image.
func Admin() address { return admin }

// Image returns the current image URL.
func Image() string { return image }

// SetImage points the ticket at another image, at once: TokenURI is computed
// on every read. Admin only, by a direct call.
func SetImage(cur realm, url string) {
	caller := cur.Previous()
	if !caller.IsUserCall() || caller.Address() != admin {
		panic(errNotAdmin)
	}
	if !validImage(url) {
		panic(errBadImage)
	}
	image = url
}

// validImage reports whether s is an https URL of 12 to 300 characters of
// [A-Za-z0-9./_-:?=&%~+]. The charset keeps it safe in JSON and markdown
// without escaping: no quote, bracket, parenthesis, space or backslash.
func validImage(s string) bool {
	if len(s) < 12 || len(s) > 300 || !strings.HasPrefix(s, "https://") {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if !(c >= 'a' && c <= 'z') && !(c >= 'A' && c <= 'Z') && !(c >= '0' && c <= '9') &&
			!strings.ContainsRune("./_-:?=&%~+", rune(c)) {
			return false
		}
	}
	return true
}

// OwnerOf returns who holds the ticket, or an error for any other id.
func OwnerOf(tid grc721.TokenID) (address, error) {
	if tid != ticket {
		return "", errors.New(errNoTicket)
	}
	return Token.OwnerOf(tid)
}

// BalanceOf returns 1 for the holder of the ticket, 0 for everyone else.
func BalanceOf(addr address) (int64, error) {
	return Token.BalanceOf(addr)
}

// TokenURI returns the image of the ticket: what Adena shows.
func TokenURI(tid grc721.TokenID) (string, error) {
	if _, err := OwnerOf(tid); err != nil {
		return "", err
	}
	return image, nil
}

// TokenMetadata returns the metadata of the ticket as JSON, with the keys
// Adena reads.
func TokenMetadata(tid grc721.TokenID) (string, error) {
	if _, err := OwnerOf(tid); err != nil {
		return "", err
	}
	return `{"name":"` + tokenName + ` #1","description":"A 1/1 on gno.land, minted to check that collections show in Adena.",` +
		`"image":"` + image + `","attributes":[{"traitType":"edition","value":"1 of 1"},{"traitType":"metal","value":"gold"}]}`, nil
}

// Transfer gives the ticket to someone else. Only its holder can, by a
// direct call (maketx call or Adena), not through another realm.
func Transfer(cur realm, to address) {
	caller := cur.Previous()
	if !caller.IsUserCall() {
		panic(errNotOwner)
	}
	if !to.IsValid() {
		panic(errBadOwner)
	}
	holder, err := Token.OwnerOf(ticket)
	if err != nil || holder != caller.Address() {
		panic(errNotOwner)
	}
	if err := ledger.TransferFrom(holder, holder, to, ticket); err != nil {
		panic(err)
	}
}

// Render shows the ticket and who holds it.
func Render(_ string) string {
	var b strings.Builder
	b.WriteString("# " + tokenName + "\n\n")
	b.WriteString("A 1/1 GRC721 on gno.land, minted to check that collections show in Adena.\n\n")
	b.WriteString("![" + tokenName + "](" + image + ")\n\n")
	holder, err := Token.OwnerOf(ticket)
	if err != nil {
		b.WriteString("Not minted.\n")
		return b.String()
	}
	b.WriteString("Held by `" + holder.String() + "`.\n")
	return b.String()
}

package goldenticket

import (
	"strings"
	"testing"

	"gno.land/p/nt/grc721/v0"
	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
)

var (
	aliceAddr = testutils.TestAddress("alice")
	bobAddr   = testutils.TestAddress("bob")
)

// reset redoes what init does on chain, with alice as the publisher.
func reset(cur realm) {
	func(cur realm) {
		bootstrap(aliceAddr, cur)
	}(cross(cur))
}

// The reads, called as Adena calls them: the id a quoted string, two values.
func TestReads(cur realm, t *testing.T) {
	reset(cur)

	owner, err := OwnerOf("1")
	uassert.NoError(t, err)
	uassert.Equal(t, aliceAddr, owner)

	n, err := BalanceOf(aliceAddr)
	uassert.NoError(t, err)
	uassert.Equal(t, int64(1), n)
	n, err = BalanceOf(bobAddr)
	uassert.NoError(t, err)
	uassert.Equal(t, int64(0), n)

	uri, err := TokenURI("1")
	uassert.NoError(t, err)
	uassert.Equal(t, defaultImage, uri)
	uassert.True(t, strings.HasPrefix(uri, "https://"))

	meta, err := TokenMetadata("1")
	uassert.NoError(t, err)
	uassert.Equal(t, `{"name":"Golden Ticket #1","description":"A 1/1 on gno.land, minted to check that collections show in Adena.",`+
		`"image":"`+defaultImage+`","attributes":[{"traitType":"edition","value":"1 of 1"},{"traitType":"metal","value":"gold"}]}`, meta)

	uassert.Equal(t, int64(1), Token.TotalSupply())
	uassert.Equal(t, "Golden Ticket", Name())
	uassert.Equal(t, "GOLD", Symbol())

	// Any other id is an error, not a panic.
	for _, bad := range []grc721.TokenID{"", "0", "2", "01", " 1"} {
		_, err = OwnerOf(bad)
		uassert.ErrorContains(t, err, errNoTicket, string(bad))
		_, err = TokenURI(bad)
		uassert.ErrorContains(t, err, errNoTicket, string(bad))
		_, err = TokenMetadata(bad)
		uassert.ErrorContains(t, err, errNoTicket, string(bad))
	}
}

func TestTransfer(cur realm, t *testing.T) {
	reset(cur)

	// Only the holder moves the ticket.
	testing.SetRealm(testing.NewUserRealm(bobAddr))
	uassert.AbortsWithMessage(t, cur, errNotOwner, func() {
		Transfer(cross(cur), bobAddr)
	})

	testing.SetRealm(testing.NewUserRealm(aliceAddr))
	uassert.AbortsWithMessage(t, cur, errBadOwner, func() {
		Transfer(cross(cur), address("nope"))
	})
	Transfer(cross(cur), bobAddr)
	owner, err := OwnerOf("1")
	uassert.NoError(t, err)
	uassert.Equal(t, bobAddr, owner)
	n, _ := BalanceOf(aliceAddr)
	uassert.Equal(t, int64(0), n)
	n, _ = BalanceOf(bobAddr)
	uassert.Equal(t, int64(1), n)

	// Not through another realm.
	testing.SetRealm(testing.NewCodeRealm("gno.land/r/demo/relay"))
	uassert.AbortsWithMessage(t, cur, errNotOwner, func() {
		Transfer(cross(cur), aliceAddr)
	})
}

func TestRender(cur realm, t *testing.T) {
	reset(cur)
	out := Render("")
	uassert.True(t, strings.Contains(out, "# Golden Ticket\n"))
	uassert.True(t, strings.Contains(out, "!["+tokenName+"]("+defaultImage+")"))
	uassert.True(t, strings.Contains(out, "Held by `"+aliceAddr.String()+"`."))
}

func TestSetImage(cur realm, t *testing.T) {
	reset(cur)
	uassert.Equal(t, aliceAddr, Admin())
	uassert.Equal(t, defaultImage, Image())

	// Only the admin, and not through another realm.
	testing.SetRealm(testing.NewUserRealm(bobAddr))
	uassert.AbortsWithMessage(t, cur, errNotAdmin, func() {
		SetImage(cross(cur), "https://example.org/a.png")
	})
	testing.SetRealm(testing.NewCodeRealm("gno.land/r/demo/relay"))
	uassert.AbortsWithMessage(t, cur, errNotAdmin, func() {
		SetImage(cross(cur), "https://example.org/a.png")
	})

	testing.SetRealm(testing.NewUserRealm(aliceAddr))
	for _, bad := range []string{
		"", "http://example.org/a.png", "https://", "javascript:alert(1)",
		"https://example.org/a b.png", `https://example.org/"a.png`, "https://example.org/a.png)![x](y",
		"https://example.org/" + strings.Repeat("a", 300),
	} {
		uassert.AbortsWithMessage(t, cur, errBadImage, func() {
			SetImage(cross(cur), bad)
		})
	}

	next := "https://ipfs.io/ipfs/bafy123/ticket.png?size=350&v=2"
	SetImage(cross(cur), next)
	uassert.Equal(t, next, Image())
	uri, err := TokenURI("1")
	uassert.NoError(t, err)
	uassert.Equal(t, next, uri)
	meta, _ := TokenMetadata("1")
	uassert.True(t, strings.Contains(meta, `"image":"`+next+`"`))
	uassert.True(t, strings.Contains(Render(""), "("+next+")"))

	// The admin stays the publisher after the ticket moves.
	Transfer(cross(cur), bobAddr)
	testing.SetRealm(testing.NewUserRealm(bobAddr))
	uassert.AbortsWithMessage(t, cur, errNotAdmin, func() {
		SetImage(cross(cur), defaultImage)
	})
}

package game

import "chain"

// Roles: one owner, a set of admins, a set of referees.
//
//   - The owner manages the admins and the treasury, and can hand the realm
//     over. The owner is always an admin.
//   - Admins tune the game and manage the referees.
//   - Referees are the game servers. They record kills and nothing else.

// callerOf returns the verified caller of a crossing function. rlm must be
// the cur of the crossing function calling this helper: a stale or forged
// realm value fails IsCurrent, and Previous is only meaningful on a live one.
//
// It takes the realm in second position on purpose, like p/nt/ownable does:
// a function whose first parameter is a realm is a crossing function.
func callerOf(_ int, rlm realm) address {
	if !rlm.IsCurrent() {
		panic(errSpoofedRealm)
	}
	return rlm.Previous().Address()
}

// assertOwner panics unless the caller is the owner, and returns the caller.
func assertOwner(_ int, rlm realm) address {
	caller := callerOf(0, rlm)
	if !owner.OwnedBy(caller) {
		panic(errNotOwner)
	}
	return caller
}

// assertAdmin panics unless the caller is an admin, and returns the caller.
func assertAdmin(_ int, rlm realm) address {
	caller := callerOf(0, rlm)
	if !IsAdmin(caller) {
		panic(errNotAdmin)
	}
	return caller
}

// assertReferee panics unless the caller is a referee, and returns the caller.
func assertReferee(_ int, rlm realm) address {
	caller := callerOf(0, rlm)
	if !IsReferee(caller) {
		panic(errNotReferee)
	}
	return caller
}

// TransferOwnership hands the realm over to newOwner. Owner only.
//
// The previous owner keeps no privilege, unless it was also added to the
// admin or referee lists.
func TransferOwnership(cur realm, newOwner address) {
	// ownable checks the caller and the address. It would take the address
	// written in capitals though, and an owner under that key could never be
	// matched to a caller again: see validAddress.
	if newOwner.IsValid() && !validAddress(newOwner) {
		panic(errInvalidAddress)
	}
	if err := owner.TransferOwnership(0, cur, newOwner); err != nil {
		panic(err)
	}
	bump()
}

// AddAdmin adds addr to the admin list. Owner only.
func AddAdmin(cur realm, addr address) {
	assertOwner(0, cur)
	if !validAddress(addr) {
		panic(errInvalidAddress)
	}
	if admins.Set(addr.String(), nil) {
		panic(errAlreadyAdmin)
	}
	bump()
	chain.Emit("AdminAdded", "address", addr.String())
}

// RemoveAdmin removes addr from the admin list. Owner only.
//
// The owner is an admin by definition and cannot be demoted this way, use
// TransferOwnership.
func RemoveAdmin(cur realm, addr address) {
	assertOwner(0, cur)
	if _, removed := admins.Remove(addr.String()); !removed {
		panic(errNoSuchAdmin)
	}
	bump()
	chain.Emit("AdminRemoved", "address", addr.String())
}

// SetTreasury sets the address the sales of skins and planes are forwarded
// to. Owner only.
func SetTreasury(cur realm, addr address) {
	assertOwner(0, cur)
	if !validAddress(addr) {
		panic(errInvalidAddress)
	}
	// Coins sent to the realm's own address would be stuck: nothing here
	// ever spends the realm balance.
	if addr == cur.Address() {
		panic(errTreasurySelf)
	}
	treasury = addr
	bump()
	chain.Emit("TreasurySet", "address", addr.String())
}

// AddReferee allows addr to submit kills. Admin only.
func AddReferee(cur realm, addr address) {
	assertAdmin(0, cur)
	if !validAddress(addr) {
		panic(errInvalidAddress)
	}
	if referees.Set(addr.String(), nil) {
		panic(errAlreadyReferee)
	}
	bump()
	chain.Emit("RefereeAdded", "address", addr.String())
}

// RemoveReferee stops addr from submitting kills. Admin only.
func RemoveReferee(cur realm, addr address) {
	assertAdmin(0, cur)
	if _, removed := referees.Remove(addr.String()); !removed {
		panic(errNoSuchReferee)
	}
	bump()
	chain.Emit("RefereeRemoved", "address", addr.String())
}

// Owner returns the owner of the realm.
func Owner() address {
	return owner.Owner()
}

// Treasury returns the address the sales of skins and planes are forwarded
// to.
func Treasury() address {
	return treasury
}

// IsAdmin reports whether addr is an admin. The owner always is.
func IsAdmin(addr address) bool {
	return owner.OwnedBy(addr) || admins.Has(addr.String())
}

// IsReferee reports whether addr may submit kills.
func IsReferee(addr address) bool {
	return referees.Has(addr.String())
}

// v0 - Unaudited: This is an initial version that has not yet been formally audited.
// Use in production at your own risk.
//
// Package game is the on-chain part of gnofly, a multiplayer plane game. It is
// the source of truth for everything an admin can tune: the game parameters,
// the roles and the treasury. It also keeps what the referee attests and what
// has lasting value: the kills, on the kill leaderboard. Skins and planes are
// tokens of their own realms, gnofly/nfts/skins and gnofly/nfts/planes, which
// ask this one who the admins are and where the treasury is.
//
// Three kinds of callers write to it:
//
//   - the owner and the admins tune the game (SetParam, ...). Every such
//     write bumps Version, which is how the game server knows it has to read
//     StateJSON again;
//   - referees, the game servers, record kills (SubmitKills).
//
// Challenge runs never reach the chain: the game server defines the
// challenges, scores the runs and keeps the session boards.
//
// Reads are plain functions meant for vm/qeval. The ones ending in JSON
// return a single string holding a JSON document. Render exposes the same
// data as markdown for gnoweb.
package game

package game

import (
	"strconv"

	"gno.land/p/nt/bptree/v0"
	"gno.land/p/nt/ownable/v0"
)

// The whole state of the realm. Everything is unexported and nothing below is
// ever returned by reference: the trees and the ownable are /p/ types with
// mutator methods, so handing one out would be handing out write access to
// the realm.
var (
	owner    *ownable.Ownable // the single owner, always an admin
	admins   bptree.BPTree    // extra admins, managed by the owner: address -> nil
	referees bptree.BPTree    // game servers allowed to submit kills: address -> nil
	treasury address          // where the sales of the skins and planes realms go

	version int64 // bumps on every admin write, see Version

	params []*param      // fixed registry, in display order
	pilots bptree.BPTree // player address -> int64 kills, allocated at the first kill

	killers ranking // the top players by kills recorded on-chain, see rankings.gno

	webPath string // "/r/g1t2kg2vtr3fukg43eujkn6x53gfdyakhngt4sfd/gnofly/game/v0", used to build links in Render
)

// init runs once, when the package is added to the chain. This is the only
// moment cur.Previous() is the deployer, so it is recorded here: the deployer
// starts as owner, referee and treasury.
//
// Under `gno test` there is no deployer and the address is empty. The tests
// call bootstrap themselves with a real address.
func init(cur realm) {
	bootstrap(cur.Previous().Address(), cur.PkgPath())
}

// bootstrap (re)creates the initial state: roles and params.
func bootstrap(deployer address, pkgPath string) {
	owner = ownable.NewWithAddress(deployer)
	admins = bptree.BPTree{}
	referees = bptree.BPTree{}
	referees.Set(deployer.String(), nil)
	treasury = deployer

	params = defaultParams()
	pilots = bptree.BPTree{}
	killers = ranking{}
	webPath = webPathOf(pkgPath)

	version = 1
}

// Version returns a counter that bumps on every admin write: params,
// treasury and roles. Referee actions (kills) do not bump it. A reader that cached StateJSON only has to read it
// again when Version changed.
func Version() int64 {
	return version
}

// bump marks the admin-tunable state as changed.
func bump() {
	version++
}

// webPathOf turns "gno.land/r/g1t2kg2vtr3fukg43eujkn6x53gfdyakhngt4sfd/gnofly/game/v0" into "/r/g1t2kg2vtr3fukg43eujkn6x53gfdyakhngt4sfd/gnofly/game/v0".
func webPathOf(pkgPath string) string {
	for i := 0; i < len(pkgPath); i++ {
		if pkgPath[i] == '/' {
			return pkgPath[i:]
		}
	}
	return ""
}

func itoa(n int64) string {
	return strconv.FormatInt(n, 10)
}

package game

import "strings"

// The JSON documents are built by hand. That is safe because every string
// that reaches them was validated against a JSON-safe charset when it was
// written (see validate.gno): ids, names, models, colors and bech32 addresses
// need no escaping. The one string that is not under the realm's control, an
// address typed into a query, goes through quote.
//
// Ordering is deterministic everywhere: params follow the registry and the
// leaderboard is best first.

// StateJSON returns everything the game needs from the chain, as one JSON
// object:
//
//	{
//	  "version": 12,
//	  "treasury": "g1...",
//	  "params": { "plane_speed": 70, "boost_speed": 130 }
//	}
//
// The output has no whitespace. It only changes when Version does. The skins
// are in their own realm, gnofly/nfts/skins.
func StateJSON() string {
	var b strings.Builder

	b.WriteString(`{"version":`)
	b.WriteString(itoa(version))
	b.WriteString(`,"treasury":"`)
	b.WriteString(treasury.String())

	b.WriteString(`","params":{`)
	for i, p := range params {
		if i > 0 {
			b.WriteByte(',')
		}
		b.WriteByte('"')
		b.WriteString(p.key)
		b.WriteString(`":`)
		b.WriteString(itoa(p.value))
	}

	b.WriteString(`}}`)
	return b.String()
}

// PlayerJSON returns one player as a JSON object:
//
//	{ "address": "g1...", "kills": 17 }
//
// The output has no whitespace. An unknown address has zero kills. The skins
// and planes a player owns are read from their realms (SkinsOf, PlanesOf).
func PlayerJSON(addr address) string {
	var b strings.Builder
	b.WriteString(`{"address":`)
	b.WriteString(quote(addr.String()))
	b.WriteString(`,"kills":`)
	b.WriteString(itoa(recordedKills(addr)))
	b.WriteByte('}')
	return b.String()
}

// KillLeaderboardJSON returns the top players by kills recorded on-chain as
// a JSON array, best first, at most leaderboard_size entries:
//
//	[ { "address": "g1...", "kills": 17 } ]
//
// The output has no whitespace. With equal kills, the player who got there
// first stays ahead.
func KillLeaderboardJSON() string {
	var b strings.Builder
	writeRanking(&b, killers, "kills")
	return b.String()
}

// quote returns s as a JSON string literal, quotes included. It is for the
// strings the realm did not validate. Quotes and backslashes are escaped and
// anything outside printable ASCII is replaced by "?", so the result is
// valid JSON whatever s holds.
func quote(s string) string {
	var b strings.Builder
	b.WriteByte('"')
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch {
		case c == '"' || c == '\\':
			b.WriteByte('\\')
			b.WriteByte(c)
		case c < 0x20 || c > 0x7e:
			b.WriteByte('?')
		default:
			b.WriteByte(c)
		}
	}
	b.WriteByte('"')
	return b.String()
}

package game

import (
	"chain"
	"errors"
)

const (
	maxKillEntries = 32   // players per SubmitKills call
	maxKillCount   = 1000 // kills per player per call

	// maxKillsLen bounds a kills string, so that an oversized input is
	// refused before it is read. An address is 40 characters, a count 4 at
	// most, plus the two separators: 64 a player leaves room to spare.
	maxKillsLen = maxKillEntries * 64
)

var errKillsFormat = errors.New(`gnofly: kills must be 1 to 32 entries "address:count" separated by ";"`)

// SubmitKills adds kills to players' on-chain counts. Referee only.
//
// kills is 1 to 32 entries "address:count" separated by ";", for example
//
//	g1abc...:3;g1def...:1
//
// Each address must be valid and listed once, each count from 1 to 1000.
// Anything else aborts the transaction and nothing is recorded. The counts
// are added to what the players already have, and the kill leaderboard is
// updated. Kills are player actions: Version does not move.
func SubmitKills(cur realm, kills string) {
	referee := assertReferee(0, cur)
	addrs, counts, err := parseKills(kills)
	if err != nil {
		panic(err)
	}

	size := leaderboardSize()
	added := int64(0)
	for i, addr := range addrs {
		total := recordedKills(addr) + counts[i]
		pilots.Set(addr.String(), total)

		if next, changed := killers.raise(addr, total-counts[i], total, size); changed {
			killers = next
		}
		added += counts[i]
	}
	chain.Emit("KillsSubmitted",
		"referee", referee.String(),
		"players", itoa(int64(len(addrs))),
		"kills", itoa(added),
	)
}

// parseKills parses and validates a kills string in a single pass. It
// returns the players and their counts, in the order of the string.
func parseKills(s string) ([]address, []int64, error) {
	if s == "" || len(s) > maxKillsLen {
		return nil, nil, errKillsFormat
	}
	var addrs []address
	var counts []int64
	seen := make(map[address]bool) // lookups only, never iterated
	i := 0
	for {
		index := len(addrs)
		if index == maxKillEntries {
			return nil, nil, errKillsFormat
		}
		colon := indexFrom(s, i, ':')
		if colon == len(s) {
			return nil, nil, errKillsFormat
		}
		end := indexFrom(s, colon+1, ';')

		addr := address(s[i:colon])
		if !validAddress(addr) {
			return nil, nil, killsEntryError(index, "invalid address")
		}
		if seen[addr] {
			return nil, nil, killsEntryError(index, "address listed twice")
		}
		// At most 4 digits: 1000 is the highest count, and a bounded length
		// keeps the number from overflowing.
		if end-colon-1 > 4 {
			return nil, nil, killsEntryError(index, "count must be a number from 1 to 1000")
		}
		count, ok := digits(s[colon+1 : end])
		if !ok || count < 1 || count > maxKillCount {
			return nil, nil, killsEntryError(index, "count must be a number from 1 to 1000")
		}
		seen[addr] = true
		addrs = append(addrs, addr)
		counts = append(counts, count)

		if end == len(s) {
			return addrs, counts, nil
		}
		i = end + 1
		if i == len(s) {
			return nil, nil, errKillsFormat // a trailing ";"
		}
	}
}

func killsEntryError(index int, reason string) error {
	return errors.New("gnofly: kills entry " + itoa(int64(index)) + ": " + reason)
}

package game

import "chain"

// param is one tunable number of the game, with the bounds an admin has to
// stay within.
type param struct {
	key   string
	value int64
	min   int64
	max   int64
	doc   string
}

// paramLeaderboardSize is the one param the realm itself consumes. Every
// other param is only stored here and applied by the game server.
const paramLeaderboardSize = "leaderboard_size"

// defaultParams returns the registry with its default values. The order is
// the display order, in StateJSON as well as in Render.
func defaultParams() []*param {
	return []*param{
		{"plane_speed", 70, 20, 300, "cruise speed, m/s"},
		{"boost_speed", 130, 20, 600, "speed while boosting, m/s"},
		{"boost_capacity_ms", 4000, 0, 60000, "how long a full boost tank lasts, 0 disables boost"},
		{"boost_recharge_ms", 10000, 100, 600000, "time to refill an empty tank while not boosting"},
		{"turn_rate", 80, 20, 360, "pitch and turn responsiveness, deg/s"},
		{"plane_health", 100, 1, 1000, "hit points"},
		{"fire_cooldown_ms", 160, 50, 5000, "minimum time between shots"},
		{"bullet_speed", 400, 100, 2000, "m/s"},
		{"bullet_ttl_ms", 1500, 100, 10000, "bullet lifetime"},
		{"bullet_damage", 20, 1, 1000, "hit points removed per bullet"},
		{"respawn_ms", 3000, 0, 60000, "delay before a destroyed plane respawns"},
		{"balloon_respawn_ms", 6000, 0, 600000, "delay before a popped balloon comes back"},
		{paramLeaderboardSize, 10, 1, 100, "entries a leaderboard keeps, on-chain and on the server"},
		{"max_players", 64, 1, 1000, "server capacity"},
		{"bot_max", 2, 0, 16, "bots flying with a lone pilot, 0 for no bots"},
		{"bot_off_players", 5, 1, 64, "from this many pilots there are no bots"},
		{"bot_aim_error", 8, 0, 45, "how far a bot's shot can stray from its aim, degrees"},
		{"bot_fire_interval_ms", 900, 100, 10000, "minimum time between a bot's shots"},
	}
}

// findParam returns the param registered under key, or nil. The registry is
// a dozen entries, a linear scan is cheaper than any index.
func findParam(key string) *param {
	for _, p := range params {
		if p.key == key {
			return p
		}
	}
	return nil
}

// SetParam changes a game parameter. Admin only.
//
// The key must exist and the value must be within the bounds of that key,
// see Render("params"). Lowering leaderboard_size truncates the kill
// leaderboard right away. Raising it does not bring back the lines that were
// dropped: the list fills up again as kills come in.
func SetParam(cur realm, key string, value int64) {
	assertAdmin(0, cur)
	p := findParam(key)
	if p == nil {
		panic(errUnknownParam)
	}
	if value < p.min || value > p.max {
		panic("gnofly: " + key + " must be between " + itoa(p.min) + " and " + itoa(p.max))
	}
	p.value = value
	if key == paramLeaderboardSize {
		trimRankings()
	}
	bump()
	chain.Emit("ParamSet", "key", key, "value", itoa(value))
}

// SetParamBounds changes the range SetParam accepts for a key. Owner only.
//
// The bounds are the guard rail between the owner and the admins: admins tune
// values within them, the owner decides how far tuning may go. The current
// value has to fit the new bounds, so that the registry never holds a value
// SetParam would refuse.
func SetParamBounds(cur realm, key string, min, max int64) {
	assertOwner(0, cur)
	p := findParam(key)
	if p == nil {
		panic(errUnknownParam)
	}
	if min < 0 || min > max {
		panic(errInvalidBounds)
	}
	// An empty leaderboard has no last line to compare a new total with.
	if key == paramLeaderboardSize && min < 1 {
		panic(errLeaderboardMin)
	}
	if p.value < min || p.value > max {
		panic(errValueOutOfBounds)
	}
	p.min, p.max = min, max
	bump()
	chain.Emit("ParamBoundsSet", "key", key, "min", itoa(min), "max", itoa(max))
}

// Param returns the value of a game parameter. It panics on an unknown key.
func Param(key string) int64 {
	p := findParam(key)
	if p == nil {
		panic(errUnknownParam)
	}
	return p.value
}

package game

// indexFrom returns the index of the first c in s at or after i, or len(s)
// when there is none.
func indexFrom(s string, i int, c byte) int {
	for i < len(s) && s[i] != c {
		i++
	}
	return i
}

// digits parses a non-empty string of decimal digits. Kill counts are never
// negative, so there is no sign to read.
func digits(s string) (int64, bool) {
	if len(s) == 0 {
		return 0, false
	}
	n := int64(0)
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c < '0' || c > '9' {
			return 0, false
		}
		n = n*10 + int64(c-'0')
	}
	return n, true
}

package game

// What the realm remembers about a player is their kills, recorded by the
// referees: pilots maps an address to an int64, allocated at the first kill.
// A player without a record has none. Skins and planes are tokens of their
// own realms (gnofly/nfts/skins, gnofly/nfts/planes).

// killsOf returns the kills recorded for addr.
func recordedKills(addr address) int64 {
	v := pilots.Get(addr.String())
	if v == nil {
		return 0
	}
	return v.(int64)
}

package game

import "strings"

// ranking is a leaderboard on a single number that only goes up, the count of
// kills: the top players, best first, at most leaderboard_size lines and one
// line per player. With equal scores, the player who got there first stays
// ahead.
//
// It is kept sorted at write time, so reading it never has to look at every
// player. Scores only going up is what makes that exact: a player outside
// the list can only enter it through raise.
//
// The two slices are parallel: slices of plain values are one stored object
// each, where a slice of structs would be one object per line. Measured on
// gnodev, a line costs about 190 bytes this way.
type ranking struct {
	addrs  []address
	scores []int64
}

// leaderboardSize returns how many lines a leaderboard may hold.
func leaderboardSize() int {
	return int(findParam(paramLeaderboardSize).value)
}

// raise puts a player at their place after their score went up from old to
// score. It returns the ranking to store, and changed == false when it is
// left as it is: the player is not on a full list and still not good enough
// to get on.
func (r ranking) raise(addr address, old, score int64, size int) (next ranking, changed bool) {
	from := r.lineOf(addr, old)
	to := r.search(score - 1) // after every line with this score or more
	if from < 0 && to >= size {
		return r, false
	}
	if from >= 0 && to > from {
		to = from // cannot happen: a score only goes up
	}
	next = ranking{
		addrs:  spliceAddrs(r.addrs, from, to, addr, size),
		scores: spliceInts(r.scores, from, to, score, size),
	}
	return next, true
}

// search returns the index of the first line with a score of limit or less,
// the number of lines when there is none. The list is sorted, so this is a
// binary search.
func (r ranking) search(limit int64) int {
	lo, hi := 0, len(r.scores)
	for lo < hi {
		mid := (lo + hi) / 2
		if r.scores[mid] <= limit {
			hi = mid
		} else {
			lo = mid + 1
		}
	}
	return lo
}

// lineOf returns the index of a player's line, -1 when they have none. old
// is the player's score before the change being applied.
//
// A line always carries the current score of its player, because every
// change of a score goes through raise. So the line can only be among those
// with exactly old, which the binary search finds without reading the whole
// list: with 32 players credited in one call on a 100 line list, comparing
// every address would cost millions of gas. A player whose score was zero
// has never been through raise and has no line.
func (r ranking) lineOf(addr address, old int64) int {
	if old <= 0 {
		return -1
	}
	for i := r.search(old); i < len(r.scores) && r.scores[i] == old; i++ {
		if r.addrs[i] == addr {
			return i
		}
	}
	return -1
}

// spliceAddrs returns a copy of a leaderboard column with v inserted at index
// to. With from >= 0 the element at that index, the player's previous line,
// is left out; to must not be past it. With from < 0 the result is kept to
// size elements by dropping the tail; to must be below size.
//
// The copy has exactly the length of its content, so that nothing else stays
// in storage, and it is built with the append builtin: on a 100 line board a
// loop over the lines costs several times more gas.
func spliceAddrs(list []address, from, to int, v address, size int) []address {
	if from < 0 {
		if len(list) >= size {
			list = list[:size-1]
		}
		out := make([]address, 0, len(list)+1)
		out = append(out, list[:to]...)
		out = append(out, v)
		return append(out, list[to:]...)
	}
	out := make([]address, 0, len(list))
	out = append(out, list[:to]...)
	out = append(out, v)
	out = append(out, list[to:from]...)
	return append(out, list[from+1:]...)
}

// spliceInts is spliceAddrs for a column of numbers.
func spliceInts(list []int64, from, to int, v int64, size int) []int64 {
	if from < 0 {
		if len(list) >= size {
			list = list[:size-1]
		}
		out := make([]int64, 0, len(list)+1)
		out = append(out, list[:to]...)
		out = append(out, v)
		return append(out, list[to:]...)
	}
	out := make([]int64, 0, len(list))
	out = append(out, list[:to]...)
	out = append(out, v)
	out = append(out, list[to:from]...)
	return append(out, list[from+1:]...)
}

// cut returns the first size lines of the ranking, in slices of exactly that
// length, so that nothing beyond the kept lines stays in storage.
func (r ranking) cut(size int) ranking {
	n := len(r.addrs)
	if n > size {
		n = size
	}
	out := ranking{addrs: make([]address, n), scores: make([]int64, n)}
	copy(out.addrs, r.addrs)
	copy(out.scores, r.scores)
	return out
}

// trimRankings cuts the kill leaderboard down to leaderboard_size.
func trimRankings() {
	if size := leaderboardSize(); len(killers.addrs) > size {
		killers = killers.cut(size)
	}
}

// writeRanking writes a ranking as a JSON array of
// {"address":"g1...","<key>":<score>} objects, best first.
func writeRanking(b *strings.Builder, r ranking, key string) {
	b.WriteByte('[')
	for i, addr := range r.addrs {
		if i > 0 {
			b.WriteByte(',')
		}
		b.WriteString(`{"address":"`)
		b.WriteString(addr.String())
		b.WriteString(`","`)
		b.WriteString(key)
		b.WriteString(`":`)
		b.WriteString(itoa(r.scores[i]))
		b.WriteByte('}')
	}
	b.WriteByte(']')
}

package game

import "strings"

// Render returns the state of the game as markdown, for gnoweb:
//
//	""               overview
//	"leaderboard"    the top players by kills
//	"params"         the game parameters and their bounds
//	"player/<addr>"  one player
//
// Everything printed here was validated against a narrow charset when it was
// written (see validate.gno), and the only caller-supplied value, the address
// of a player page, is printed only if it is a valid address. Nothing needs
// markdown escaping.
func Render(path string) string {
	switch {
	case path == "":
		return renderHome()
	case path == "leaderboard":
		return renderLeaderboard()
	case path == "params":
		return renderParams()
	case strings.HasPrefix(path, "player/"):
		return renderPlayer(address(strings.TrimPrefix(path, "player/")))
	}
	return "# gnofly\n\nPage not found. Go back to the [overview](" + link("") + ").\n"
}

// link returns the gnoweb URL of a Render path of this realm.
func link(path string) string {
	if path == "" {
		return webPath
	}
	return webPath + ":" + path
}

func renderHome() string {
	var b strings.Builder
	b.WriteString("# gnofly\n\n")
	b.WriteString("A multiplayer plane game. Fly through rings, pop balloons, shoot down the other pilots.\n")
	b.WriteString("This realm holds the rules of the game: parameters, roles and the kills that count.\n\n")

	b.WriteString("- [Leaderboard](" + link("leaderboard") + "): " + itoa(int64(len(killers.addrs))) + " ranked pilots\n")
	b.WriteString("- [Parameters](" + link("params") + "): " + itoa(int64(len(params))) + "\n\n")

	b.WriteString("| | |\n|---|---|\n")
	b.WriteString("| Version | " + itoa(version) + " |\n")
	b.WriteString("| Owner | " + owner.Owner().String() + " |\n")
	b.WriteString("| Treasury | " + treasury.String() + " |\n")
	b.WriteString("| Admins | " + itoa(int64(admins.Size())) + " besides the owner |\n")
	b.WriteString("| Referees | " + itoa(int64(referees.Size())) + " |\n")
	b.WriteString("| Pilots on record | " + itoa(int64(pilots.Size())) + " |\n")
	return b.String()
}

func renderLeaderboard() string {
	var b strings.Builder
	b.WriteString("# gnofly leaderboard\n\n")
	b.WriteString("## Most kills\n\n")
	b.WriteString("Kills recorded on-chain by the game servers. The table keeps its top " +
		itoa(int64(leaderboardSize())) + " pilots.\n\n")
	if len(killers.addrs) == 0 {
		b.WriteString("No kill was recorded yet.\n")
	} else {
		b.WriteString("| Rank | Pilot | Kills |\n|---|---|---|\n")
		for i, a := range killers.addrs {
			b.WriteString("| " + itoa(int64(i+1)) + " | " + pilotLink(a) + " | " + itoa(killers.scores[i]) + " |\n")
		}
	}
	b.WriteString("\n[Back to the overview](" + link("") + ")\n")
	return b.String()
}

// pilotLink returns a markdown link to the page of a player.
func pilotLink(addr address) string {
	a := addr.String()
	return "[" + a + "](" + link("player/"+a) + ")"
}

func renderParams() string {
	var b strings.Builder
	b.WriteString("# gnofly parameters\n\n")
	b.WriteString("Admins change a value with `SetParam`, within its bounds.\n\n")
	b.WriteString("| Key | Value | Min | Max | Meaning |\n|---|---|---|---|---|\n")
	for _, p := range params {
		b.WriteString("| " + p.key + " | " + itoa(p.value) + " | " + itoa(p.min) + " | " + itoa(p.max) + " | " + p.doc + " |\n")
	}
	b.WriteString("\n[Back to the overview](" + link("") + ")\n")
	return b.String()
}

func renderPlayer(addr address) string {
	// The address comes from the URL: never print it unless it is one.
	if !validAddress(addr) {
		return "# gnofly pilot\n\nThis is not a valid address. Go back to the [overview](" + link("") + ").\n"
	}
	var b strings.Builder
	b.WriteString("# gnofly pilot\n\n")
	b.WriteString("| | |\n|---|---|\n")
	b.WriteString("| Address | " + addr.String() + " |\n")
	b.WriteString("| Kills | " + itoa(recordedKills(addr)) + " |\n")
	b.WriteString("\n[Leaderboard](" + link("leaderboard") + ") | [Overview](" + link("") + ")\n")
	return b.String()
}

package game

// validAddress is the one string rule of this realm: the addresses it keys
// on. Everything else it prints is a number, a param key from its own
// registry or an address checked here.

// validAddress reports whether addr is a valid address in its canonical,
// lowercase form.
//
// Bech32 can also be written in all capitals, and address.IsValid accepts
// that. To this realm the capitals would be a second key for the same
// account: a second player record, a second line on a leaderboard, an admin
// who can never be matched to a caller. Bech32 does not allow mixing cases,
// so looking at the first character is enough.
func validAddress(addr address) bool {
	return addr.IsValid() && addr[0] == 'g'
}

// v0 - Unaudited: This is an initial version that has not yet been formally audited.
// Use in production at your own risk.
//
// Package planes is a collection of 777 plane NFTs that pilots fly in
// gnofly, a multiplayer plane game. It is a GRC721 token built on
// gno.land/p/nt/grc721/v0 with the royalty extension.
//
// Every plane is drawn in a table committed with the realm (table.gno): a
// name, one of the nine models the game client draws, a pilot (none or a
// gnome), three colours, a tier and the colour of its laser, the shots
// every pilot sees it fire. The designs stay procedural in the client; the
// token stores only these traits. Id 777 is the super-gnome, a
// 1/1 that is a gnome flying like a superhero rather than a plane. The table
// is public; which ids a mint gets is drawn at random among the ones left,
// 1 to 7 per call (draw.gno).
//
// Three kinds of callers write to it:
//
//   - anyone mints the next plane with the price attached (Mint), transfers,
//     approves and burns their planes (TransferFrom, Approve,
//     SetApprovalForAll, Burn);
//   - the admins of the game realm open and close the mint and tune its
//     price, its per-wallet cap, the image URL and the royalty (SetMintOpen,
//     SetPrice, SetMintCap, SetImageBase, SetRoyaltyBps);
//   - nobody else: there is no reserve and no airdrop.
//
// The realm keeps no roles and no money of its own. The admins are those of
// gno.land/r/g1t2kg2vtr3fukg43eujkn6x53gfdyakhngt4sfd/gnofly/game/v0, asked
// at the time of each call, and every mint is forwarded to its treasury in
// the same transaction. The royalty of a resale, 5% by default, names the
// treasury too.
//
// Reads are plain functions meant for vm/qeval. The ones ending in JSON
// return a single string holding a JSON document. PlanesOf and OwnerOf are
// what the game server reads: ownership is the only on-chain fact of a
// plane, which one a pilot flies is picked in the game's hangar and checked
// against OwnerOf by the server. Render exposes the
// same data as markdown for gnoweb. The read side of the token and of its
// royalty extension is exported as Token and Royalties, for other realms.
// No metadata is stored per token: TokenMetadata and TokenURI are computed
// from the table and the image base on every read.
//
// Storage is paid for at deploy, so the realm is kept small: the table is one
// string read in place, refusals are string constants, and the settings are
// read through CollectionJSON rather than one getter each.
package planes

package planes

import (
	"chain/runtime"
	"crypto/sha256"
	"encoding/binary"
	"time"
)

// Planes are minted in a random order: each mint draws one of the ids not
// minted yet. The id drawn is the token id and the row of the table, so
// whoever draws 777 gets the SuperGnome.
//
// The pool of ids left is a byte string of two bytes per id, big-endian,
// 1554 bytes at deploy: a slice of 777 int64 would cost several times the
// storage. A draw takes the id at a random index and moves the last id into
// its place (swap-remove), so every id comes out exactly once and a draw
// costs the same at any point of the sale.
//
// The randomness is pseudo-random, from what a realm can see: the sha256 of
// the block height, the block time, the minter, the count minted so far and
// the hash of the previous draw. A validator could nudge the block time, a
// user could try to time their block; nobody can see a draw and undo it,
// because Mint only accepts direct user calls (a contract cannot call Mint,
// look at the id and panic to try again). That is enough for this
// collection; it is not for anything with money riding on the outcome.

// pool holds the ids not minted yet, two bytes each. Its length over two is
// how many are left.
var pool []byte

// mintedBits has one bit per id, set once the id is minted (burned or not):
// what tells a burned plane from one not minted yet, without scanning pool.
var mintedBits []byte

// lastDraw is the hash of the previous draw, chained into the next.
var lastDraw [32]byte

// testDraw, when set by a test, replaces the hash to pick an index in a pool
// of n ids. It is never set outside the tests.
var testDraw func(n int) int

// resetPool fills the pool with every id, from 777 down to 1, and seeds the
// chain of draws from the realm's path.
func resetPool(pkgPath string) {
	pool = make([]byte, 2*supply)
	for i := int64(0); i < supply; i++ {
		binary.BigEndian.PutUint16(pool[2*i:], uint16(supply-i))
	}
	mintedBits = make([]byte, (supply+7)/8)
	lastDraw = sha256.Sum256([]byte(pkgPath))
}

// left returns how many ids are not minted yet.
func left() int64 {
	return int64(len(pool) / 2)
}

// drawHash is the hash a draw picks its index from. It is a pure function of
// its inputs, so that the tests can check what moves it.
func drawHash(height, nanos int64, minter address, minted int64, prev [32]byte) [32]byte {
	buf := make([]byte, 0, 8+8+len(minter)+8+32)
	buf = binary.BigEndian.AppendUint64(buf, uint64(height))
	buf = binary.BigEndian.AppendUint64(buf, uint64(nanos))
	buf = append(buf, minter...)
	buf = binary.BigEndian.AppendUint64(buf, uint64(minted))
	buf = append(buf, prev[:]...)
	return sha256.Sum256(buf)
}

// drawID takes one id out of the pool, at random, for minter, and marks it
// minted. The pool must not be empty.
func drawID(minter address) int64 {
	n := len(pool) / 2
	var i int
	if testDraw != nil {
		i = testDraw(n)
	} else {
		lastDraw = drawHash(runtime.ChainHeight(), time.Now().UnixNano(), minter, Minted(), lastDraw)
		// The first 8 bytes modulo the pool size: the bias of a modulo of
		// 2^64 by at most 777 is under 777/2^64, nothing.
		i = int(binary.BigEndian.Uint64(lastDraw[:8]) % uint64(n))
	}
	id := int64(binary.BigEndian.Uint16(pool[2*i:]))
	copy(pool[2*i:2*i+2], pool[2*(n-1):2*n])
	pool = pool[:2*(n-1)]
	mintedBits[(id-1)/8] |= 1 << uint((id-1)%8)
	return id
}

// wasMinted reports whether id was ever minted, burned since or not.
func wasMinted(id int64) bool {
	if id < 1 || id > supply {
		return false
	}
	return mintedBits[(id-1)/8]&(1<<uint((id-1)%8)) != 0
}

package planes

// The refusals of this realm, as strings. The game and arena realms keep
// theirs as error values; this one is published with a 42 KB table and every
// byte of state is paid for at deploy. Measured on a mainnet-like node, an
// errors.New value costs about 1.15 KB of storage (a pointer, a heap item and
// a struct, each with its header) where a string constant costs its length:
// twenty of them are 2 GNOT against 0.1. A panic with a string aborts the
// call with the same message.
const (
	errSpoofedRealm = "gnofly: spoofed realm"
	errNotAdmin     = "gnofly: caller is not an admin"
	errBadTable     = "gnofly: the plane table does not run from 1 to 777"
	errCorruptRow   = "gnofly: corrupt plane row"

	errUnknownPlane  = "gnofly: unknown plane"
	errNotMinted     = "gnofly: plane not minted"
	errNotPlaneOwner = "gnofly: caller does not own this plane"

	errMintClosed   = "gnofly: the mint is closed"
	errSoldOut      = "gnofly: every plane is minted"
	errCapReached   = "gnofly: this wallet minted as many planes as the cap allows"
	errNotUserCall  = "gnofly: Mint must be called directly by a user (maketx call)"
	errInvalidCount = "gnofly: mint 1 to 7 planes at a time"

	errInvalidPrice   = "gnofly: price must be between 1000000 and 10000000000 ugnot"
	errInvalidCap     = "gnofly: cap must be between 1 and 777"
	errInvalidBase    = "gnofly: image base must be an https URL ending in /, 12 to 200 characters of [A-Za-z0-9./_-:]"
	errInvalidRoyalty = "gnofly: royalty must be between 0 and 1000 basis points"
)

package planes

import (
	"strings"

	"gno.land/p/onbloc/json/v0"
)

// The JSON documents are built with gno.land/p/onbloc/json/v0, which quotes
// every string. Keys come out in the order they are written: a gno map
// iterates in insertion order, and the library keeps an object's members in
// one. Numbers are float64 in the library and printed without exponent or
// decimal point when whole, which every number here is, far under 2^53.

// PlaneJSON returns one plane as a JSON object, minted or not:
//
//	{ "id": 42, "name": "Storm Saint", "model": "delta", "pilot": "gnome",
//	  "body": "#1e1b4b", "wing": "#1e293b", "accent": "#00f5ff", "tier": "epic",
//	  "laser": "#39ff14", "image": "https://gnofly.xyz/nft/collections/planes/042.png", "owner": "g1..." }
//
// The output has no whitespace. "owner" is "" for a plane not minted, or
// burned. An id outside 1 to 777 returns "". Which plane a pilot flies is
// not on-chain: the game server checks the owner when a pilot picks one.
func PlaneJSON(id int64) string {
	p, ok := getPlane(id)
	if !ok {
		return ""
	}
	b := json.Builder()
	writePlane(b, p)
	b.WriteString("image", imageURL(id))
	b.WriteString("owner", ownerOf(id).String())
	return encode(b.Node())
}

// PlanesOf returns the ids of the planes addr owns as a JSON array, in
// ascending order: [3,42,700]. It is [] for an address without planes.
func PlanesOf(addr address) string {
	ids := []*json.Node{}
	if n, err := Token.BalanceOf(addr); err == nil && n > 0 {
		// Ids are dense, 1 to 777: a scan that stops at the last plane of
		// addr is cheaper than keeping a list per owner up to date at every
		// mint and transfer.
		for id := int64(1); id <= supply && int64(len(ids)) < n; id++ {
			if ownerOf(id) == addr {
				ids = append(ids, json.NumberNode("", float64(id)))
			}
		}
	}
	return encode(json.ArrayNode("", ids))
}

// maxMintedPage is the most ids MintedJSON looks at in one call.
const maxMintedPage = int64(200)

// MintedJSON returns who owns the minted planes among the ids offset+1 to
// offset+limit, as a JSON array in id order:
//
//	[{"id":3,"owner":"g1..."},{"id":42,"owner":""},...]
//
// Ids not minted are left out; "owner" is "" for a burned plane. limit is
// capped at 200, so four calls (offsets 0, 200, 400, 600) cover the 777,
// whatever was minted: planes are drawn at random, minted ids are not a
// prefix. It is what the website's grid reads. An empty range is [].
func MintedJSON(offset, limit int64) string {
	if limit > maxMintedPage {
		limit = maxMintedPage
	}
	entries := []*json.Node{}
	if offset >= 0 && limit > 0 {
		last := offset + limit
		if last > supply {
			last = supply
		}
		for id := offset + 1; id <= last; id++ {
			if !wasMinted(id) {
				continue
			}
			entry := json.Builder().
				WriteNumber("id", float64(id)).
				WriteString("owner", ownerOf(id).String())
			entries = append(entries, entry.Node())
		}
	}
	return encode(json.ArrayNode("", entries))
}

// CollectionJSON returns the state of the collection as one JSON object:
//
//	{ "name": "gnofly planes", "symbol": "PLANE",
//	  "supply": 777, "minted": 12, "burned": 0,
//	  "price": 77000000, "open": true, "cap": 7,
//	  "royaltyBps": 500, "treasury": "g1...",
//	  "imageBase": "https://gnofly.xyz/nft/collections/planes/",
//	  "tiers": { "common": { "supply": 500, "minted": 8 },
//	             "rare": { "supply": 200, "minted": 3 },
//	             "epic": { "supply": 70, "minted": 1 },
//	             "legendary": { "supply": 7, "minted": 0 } } }
//
// The output has no whitespace. "minted" counts every mint so far, burned
// planes included; "minted" minus "burned" is what exists.
func CollectionJSON() string {
	b := json.Builder().
		WriteString("name", tokenName).
		WriteString("symbol", tokenSymbol).
		WriteNumber("supply", float64(supply)).
		WriteNumber("minted", float64(Minted())).
		WriteNumber("burned", float64(Minted()-Token.TotalSupply())).
		WriteNumber("price", float64(price)).
		WriteBool("open", mintOpen).
		WriteNumber("cap", float64(mintCap)).
		WriteNumber("royaltyBps", float64(RoyaltyBps())).
		WriteString("treasury", roles.Treasury().String()).
		WriteString("imageBase", imageBase).
		WriteObject("tiers", func(tb *json.NodeBuilder) {
			for i, tier := range strings.Split(tiers, ",") {
				tb.WriteObject(tier, func(t *json.NodeBuilder) {
					t.WriteNumber("supply", float64(tierSupply[i]))
					t.WriteNumber("minted", float64(tierMinted[i]))
				})
			}
		})
	return encode(b.Node())
}

// writePlane writes the nine fields of a plane, in the order of a row, so
// that a caller can add fields after them.
func writePlane(b *json.NodeBuilder, p plane) {
	b.WriteNumber("id", float64(p.id)).
		WriteString("name", p.name).
		WriteString("model", p.model).
		WriteString("pilot", p.pilot).
		WriteString("body", p.body).
		WriteString("wing", p.wing).
		WriteString("accent", p.accent).
		WriteString("tier", p.tier).
		WriteString("laser", p.laser)
}

// encode marshals a document built above. It cannot fail on a document
// built from the builder, so a failure is a bug and panics.
func encode(n *json.Node) string {
	out, err := json.Marshal(n)
	if err != nil {
		panic(err)
	}
	return string(out)
}

package planes

import (
	"chain"
	"chain/banker"
	"errors"

	// Only for OriginSend, in Mint. Caller identity always comes from
	// cur.Previous(), never from this package.
	"chain/runtime/unsafe"

	"gno.land/p/nt/grc721/v0"
	"gno.land/p/onbloc/json/v0"
)

// maxBatch is the most planes one Mint call mints. It is a constant, apart
// from the per-wallet cap that admins tune with SetMintCap.
const maxBatch = int64(7)

// Mint mints count planes for the caller, 1 to 7 in one call, drawn at
// random among the ids not minted yet (draw.gno), and returns their ids in
// the order drawn. Exactly
// count times the price must be attached to the transaction (-send
// "<count*price>ugnot"); it is forwarded to the treasury of the game realm,
// in one send, before the call returns.
//
// Each id comes out once, while the mint is open. A batch is
// minted whole or not at all: one that would take the caller over the
// per-wallet cap, or past the last plane, is refused with how many are left.
// It must be called directly by a user (maketx call): a call relayed by
// another realm or by a maketx run script is refused. That is also what
// keeps the draw fair: a contract could otherwise look at the ids it got
// and panic to draw again.
//
// The caller pays the storage of their planes as a deposit on top of the
// price, given back on burn: the ledger entries only, the traits stay in the
// table (see the numbers in docs/spec.md, section 9.2).
func Mint(cur realm, count int64) []int64 {
	minter := callerOf(0, cur)

	// Paid-call guard: two checks that are only correct together.
	//
	// (a) The caller is a plain user account. Only then is the -send
	//     envelope guaranteed to have landed at this realm's address. A
	//     relaying realm or a maketx run script can attach coins to the
	//     transaction and keep them, while OriginSend still reports them.
	if !cur.Previous().IsUserCall() {
		panic(errNotUserCall)
	}
	if count < 1 || count > maxBatch {
		panic(errInvalidCount)
	}
	if !mintOpen {
		panic(errMintClosed)
	}
	if n := left(); n < 1 {
		panic(errSoldOut)
	} else if count > n {
		panic("gnofly: only " + itoa(n) + " planes are left to mint")
	}
	if left := mintCap - mintedBy(minter); left < 1 {
		panic(errCapReached)
	} else if count > left {
		panic("gnofly: this wallet can mint " + itoa(left) + " more planes, the cap is " + itoa(mintCap))
	}

	// (b) The envelope is exactly count times the price: one coin, the right
	//     denom, the right amount. Anything else would either underpay or
	//     leave coins behind in the realm.
	total := count * price
	sent := unsafe.OriginSend()
	if len(sent) != 1 || sent[0].Denom != payDenom || sent[0].Amount != total {
		panic("gnofly: wrong payment, send exactly " + itoa(total) + payDenom)
	}

	// Forward the payment right away, so that nothing accrues in the realm.
	// An OriginSend banker can spend the envelope of this call and nothing
	// else.
	treasury := roles.Treasury()
	payment := chain.NewCoins(chain.NewCoin(payDenom, total))
	banker.NewBanker(banker.BankerTypeOriginSend, cur).SendCoins(cur.Address(), treasury, payment)

	ids := make([]int64, 0, count)
	for i := int64(0); i < count; i++ {
		p := mustPlane(drawID(minter))
		mintCount++
		ids = append(ids, p.id)
		copy(recent[1:], recent[:len(recent)-1])
		recent[0] = p.id
		if err := ledger.Mint(minter, tokenID(p.id)); err != nil {
			panic(err)
		}
		tierMinted[tierIndex(p.tier)]++
		chain.Emit("PlaneMinted",
			"id", itoa(p.id),
			"minter", minter.String(),
			"price", itoa(price),
			"treasury", treasury.String(),
		)
	}
	mints.Set(minter.String(), mintedBy(minter)+count)
	return ids
}

// mintedBy returns how many planes addr minted so far.
func mintedBy(addr address) int64 {
	v := mints.Get(addr.String())
	if v == nil {
		return 0
	}
	return v.(int64)
}

// The read functions a wallet calls take a grc721.TokenID and return an
// error rather than panic, the way Adena calls them: OwnerOf("42") into two
// values, TokenURI("42") as the image it shows, TokenMetadata("42") as JSON
// for the traits. The errors are made on the call, not stored: a stored
// error value costs a kilobyte of deposit (see errors.gno).

// TokenMetadata returns the metadata of a minted plane as JSON, built from
// the table on every read: the realm stores no metadata per token.
//
//	{"name":"Storm Saint","description":"Plane 42 of 777, ...",
//	 "image":"https://gnofly.xyz/nft/collections/planes/042.png",
//	 "attributes":[{"traitType":"model","value":"delta"}, ...]}
//
// The keys are the ones Adena reads, traitType included.
func TokenMetadata(tid grc721.TokenID) (string, error) {
	id, err := mintedID(tid)
	if err != nil {
		return "", err
	}
	p := mustPlane(id)
	b := json.Builder().
		WriteString("name", p.name).
		WriteString("description", description(p)).
		WriteString("image", imageURL(id)).
		WriteArray("attributes", func(ab *json.ArrayBuilder) {
			for _, t := range [][2]string{
				{"model", p.model}, {"pilot", p.pilot}, {"body", p.body}, {"wing", p.wing},
				{"accent", p.accent}, {"tier", p.tier}, {"laser", p.laser},
			} {
				ab.WriteObject(func(o *json.NodeBuilder) {
					o.WriteString("traitType", t[0]).WriteString("value", t[1])
				})
			}
		})
	return encode(b.Node()), nil
}

// mintedID reads a token id, "1" to "777", and checks the plane is minted.
func mintedID(tid grc721.TokenID) (int64, error) {
	id := parseID(string(tid))
	if ownerOf(id) == "" {
		return 0, errors.New(errNotMinted)
	}
	return id, nil
}

// parseID reads "1" to "777" in decimal, 0 for anything else.
func parseID(s string) int64 {
	if len(s) == 0 || len(s) > 3 || s[0] == '0' {
		return 0
	}
	n := int64(0)
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return 0
		}
		n = n*10 + int64(s[i]-'0')
	}
	if n > supply {
		return 0
	}
	return n
}

// description is one sentence about a plane: "Plane 42 of 777, an epic delta
// flown by a gnome." The tier is the only word that may start with a vowel.
func description(p plane) string {
	article := "a "
	if p.tier == "epic" {
		article = "an "
	}
	s := "Plane " + itoa(p.id) + " of " + itoa(supply) + ", " + article + p.tier + " " + p.model
	if p.pilot == "gnome" {
		s += " flown by a gnome"
	}
	return s + "."
}

// Burn destroys a plane. Only its owner can, and nobody can mint it again:
// the id stays out of circulation.
func Burn(cur realm, id int64) {
	caller := callerOf(0, cur)
	if ownerOf(id) != caller {
		panic(errNotPlaneOwner)
	}
	if err := ledger.Burn(tokenID(id)); err != nil {
		panic(err)
	}
	chain.Emit("PlaneBurned", "id", itoa(id), "owner", caller.String())
}

// The GRC721 transfer surface. These wrappers hand cur to the caller-scoped
// teller, which acts as cur.Previous() and applies it to the private ledger:
// a caller moves their own planes and the ones they were approved for,
// nothing else. See p/nt/grc721/v0/tellers.gno.

// TransferFrom moves plane id from one address to another. The caller must
// own it or be approved for it.
func TransferFrom(cur realm, from, to address, id int64) {
	if err := teller.TransferFrom(0, cur, from, to, tokenID(id)); err != nil {
		panic(err)
	}
}

// Approve lets to move plane id once. The caller must own it. An empty
// address revokes.
func Approve(cur realm, to address, id int64) {
	if err := teller.Approve(0, cur, to, tokenID(id)); err != nil {
		panic(err)
	}
}

// SetApprovalForAll lets operator move every plane of the caller, or
// revokes it.
func SetApprovalForAll(cur realm, operator address, approved bool) {
	if err := teller.SetApprovalForAll(0, cur, operator, approved); err != nil {
		panic(err)
	}
}

// ownerOf returns who owns plane id, or "" when it is not minted.
func ownerOf(id int64) address {
	if id < 1 || id > supply {
		return ""
	}
	owner, err := Token.OwnerOf(tokenID(id))
	if err != nil {
		return ""
	}
	return owner
}

// OwnerOf returns who owns plane tid, or an error when it is not minted.
func OwnerOf(tid grc721.TokenID) (address, error) {
	id, err := mintedID(tid)
	if err != nil {
		return "", err
	}
	return ownerOf(id), nil
}

// BalanceOf returns how many planes addr owns.
func BalanceOf(addr address) (int64, error) {
	return Token.BalanceOf(addr)
}

// TotalSupply returns how many planes exist: minted and not burned.
func TotalSupply() int64 {
	return Token.TotalSupply()
}

// GetApproved returns the address approved to move plane id, or "" when
// there is none.
func GetApproved(id int64) address {
	addr, err := Token.GetApproved(tokenID(id))
	if err == grc721.ErrTokenIdNotApproved {
		return ""
	}
	if err != nil {
		panic(err)
	}
	return addr
}

// IsApprovedForAll reports whether operator may move every plane of owner.
func IsApprovedForAll(owner, operator address) bool {
	return Token.IsApprovedForAll(owner, operator)
}

// TokenURI returns the image of a minted plane, "<image base><nnn>.png":
// what a wallet shows (Adena puts it in an <img>). The metadata is
// TokenMetadata, or "<image base><id>.json" on the website. It is computed,
// not stored: a mint writes no URI.
func TokenURI(tid grc721.TokenID) (string, error) {
	id, err := mintedID(tid)
	if err != nil {
		return "", err
	}
	return imageURL(id), nil
}

// RoyaltyInfo returns who receives the royalty on a sale of plane id at
// salePrice, and how much: EIP-2981.
func RoyaltyInfo(id int64, salePrice int64) (address, int64) {
	receiver, amount, err := Royalties.RoyaltyInfo(tokenID(id), salePrice)
	if err != nil {
		panic(err)
	}
	return receiver, amount
}

// RoyaltyBps returns the royalty of a resale, in basis points.
func RoyaltyBps() int64 {
	info, ok := Royalties.DefaultRoyalty()
	if !ok {
		return 0
	}
	return info.Bps
}

package planes

import (
	"chain"
	"strconv"
	"strings"

	"gno.land/p/nt/bptree/v0"
	"gno.land/p/nt/grc721/royalty/v0"
	"gno.land/p/nt/grc721/v0"
)

// The read side of the collection, exported for other realms and for
// vm/qeval, as GRC721 tokens are on gno.land. Neither type has a mutator: a
// Token hands out tellers that act as the calling realm and go through the
// ledger's approval checks, Royalty only reads. There is no metadata
// extension: the traits are in the table, read with TokenMetadata(tid) and
// PlaneJSON(id), and the token URI, the image, is computed by TokenURI(tid).
//
//	planes.TokenMetadata("42")
//	planes.Token.RealmTeller(0, cur).TransferFrom(0, cur, from, to, "42")
var (
	Token     *grc721.Token    // name, symbol, owners, balances, approvals
	Royalties *royalty.Royalty // EIP-2981 royalty
)

// The rest of the state. Everything is unexported and nothing below is ever
// returned by reference: the ledgers and the trees are /p/ types with mutator
// methods, so handing one out would be handing out write access to the
// collection.
var (
	ledger        *grc721.PrivateLedger // the collection, write side: mint, burn
	teller        grc721.Teller         // acts as the caller of this realm: transfers and approvals
	royaltyLedger *royalty.Ledger       // royalty, write side

	mintCount int64  // planes minted so far, burned ones included; the ids left are in pool (draw.gno)
	price     int64  // ugnot, what a mint costs
	mintOpen  bool   // whether Mint is accepting calls
	mintCap   int64  // how many planes one wallet may mint, over its lifetime
	imageBase string // "https://gnofly.xyz/nft/collections/planes/", the image of plane 42 is at <base>042.png

	mints      bptree.BPTree // minter address -> int64, planes minted so far, for the cap
	tierMinted [4]int64      // planes minted so far per tier, in the order of tiers
	recent     [5]int64      // the last ids minted, newest first, 0 for none, for Render

	webPath string // "/r/g1t2kg2vtr3fukg43eujkn6x53gfdyakhngt4sfd/gnofly/nfts/planes", used to build links in Render
)

// The collection, and the settings at deploy.
const (
	supply      = int64(777)
	tokenName   = "gnofly planes"
	tokenSymbol = "PLANE"
	payDenom    = "ugnot" // the only coin planes are sold for

	defaultPrice     = int64(77000000) // 77 GNOT
	minPrice         = int64(1000000)
	maxPrice         = int64(10000000000)
	defaultMintCap   = int64(7)
	defaultImageBase = "https://gnofly.xyz/nft/collections/planes/"

	defaultRoyaltyBps = int64(500)  // 5% of a resale, to the treasury
	maxRoyaltyBps     = int64(1000) // the most SetRoyaltyBps accepts

	// Models are what the game client renders, tiers are what the table
	// says. Both are validated against these lists.
	models = "prop,biplane,stunt,jet,seaplane,twin,delta,glider,supergnome"
	pilots = "none,gnome"
	tiers  = "common,rare,epic,legendary"
)

// tierSupply is how many planes of each tier the table holds, in the order
// of tiers. The tests check it against the table.
var tierSupply = [4]int64{500, 200, 70, 7}

// tierIndex returns the position of tier in tiers, or -1.
func tierIndex(tier string) int {
	for i, t := range strings.Split(tiers, ",") {
		if t == tier {
			return i
		}
	}
	return -1
}

// init runs once, when the package is added to the chain. The realm has
// nothing to remember about its deployer: it has no role of its own.
func init(cur realm) {
	bootstrap(0, cur)
}

// bootstrap (re)creates the initial state: the token, its extensions and the
// settings. The tests call it to start from a clean slate. rlm is the live
// realm of the caller: grc721 records its package path as the home of the
// Token.
func bootstrap(_ int, rlm realm) {
	// A table of the wrong shape is refused before anything is written, so
	// that a bad hand edit fails at publish rather than at the first mint.
	if first, last := rowID(0), rowID(len(table)-1); first != 1 || last != supply {
		panic(errBadTable)
	}

	Token, ledger = grc721.NewToken(tokenName, tokenSymbol, 0, rlm)
	// Minted from the ledger: the frame-relative teller is confined to this
	// realm, which is where it is used.
	teller = ledger.CallerTeller()
	Royalties, royaltyLedger = royalty.NewRoyalty(ledger, maxRoyaltyBps)

	mintCount = 0
	resetPool(rlm.PkgPath())
	recent = [5]int64{}
	price = defaultPrice
	mintOpen = false
	mintCap = defaultMintCap
	imageBase = defaultImageBase
	mints = bptree.BPTree{}
	tierMinted = [4]int64{}
	webPath = webPathOf(rlm.PkgPath())

	// Under `gno test` the game realm has no treasury yet (see roles.gno):
	// the tests set one and call bootstrap again.
	if roles.Treasury().IsValid() {
		setRoyalty(defaultRoyaltyBps)
	}
}

// setRoyalty points the royalty of every plane at the treasury of the game
// realm, as it is now, at bps basis points.
func setRoyalty(bps int64) {
	if err := royaltyLedger.SetDefaultRoyalty(roles.Treasury(), bps); err != nil {
		panic(err)
	}
}

// SetMintOpen opens or closes the mint. Admin only. The mint starts closed.
func SetMintOpen(cur realm, open bool) {
	assertAdmin(0, cur)
	mintOpen = open
	chain.Emit("MintOpen", "open", boolString(open))
}

// SetPrice sets what a mint costs, from 1 to 10000 GNOT. Admin only. It
// applies to the next mint.
func SetPrice(cur realm, ugnot int64) {
	assertAdmin(0, cur)
	if ugnot < minPrice || ugnot > maxPrice {
		panic(errInvalidPrice)
	}
	price = ugnot
	chain.Emit("PriceSet", "price", itoa(ugnot))
}

// SetMintCap sets how many planes one wallet may mint over its lifetime, from
// 1 to 777. Admin only. A wallet already over a lowered cap keeps its planes
// and mints no more.
func SetMintCap(cur realm, n int64) {
	assertAdmin(0, cur)
	if n < 1 || n > supply {
		panic(errInvalidCap)
	}
	mintCap = n
	chain.Emit("MintCapSet", "cap", itoa(n))
}

// SetImageBase sets where the images and the metadata of the planes are
// served from: the image of plane 42 is <base>042.png and its token URI is
// <base>42.json. Admin only.
//
// It applies at once to every plane: the URLs are computed on read, nothing
// is stored per token.
func SetImageBase(cur realm, base string) {
	assertAdmin(0, cur)
	if !validBase(base) {
		panic(errInvalidBase)
	}
	imageBase = base
	chain.Emit("ImageBaseSet", "base", base)
}

// SetRoyaltyBps sets the royalty of a resale, from 0 to 1000 basis points,
// and points it at the treasury of the game realm as it is now. Admin only.
//
// The royalty is advisory, as EIP-2981 is: a marketplace reads RoyaltyInfo
// and pays it, the realm cannot enforce it on a transfer.
func SetRoyaltyBps(cur realm, bps int64) {
	assertAdmin(0, cur)
	if bps < 0 || bps > maxRoyaltyBps {
		panic(errInvalidRoyalty)
	}
	setRoyalty(bps)
}

// Minted returns how many planes were minted so far, burned ones included.
// Planes are drawn at random, so it says nothing of which ids. The
// settings (price, open, cap, image base, royalty) are read with
// CollectionJSON: every exported function costs storage at deploy, measured
// at about 650 bytes each, so there is no getter per setting.
func Minted() int64 {
	return mintCount
}

// webPathOf turns "gno.land/r/g1t2kg2vtr3fukg43eujkn6x53gfdyakhngt4sfd/gnofly/nfts/planes" into "/r/g1t2kg2vtr3fukg43eujkn6x53gfdyakhngt4sfd/gnofly/nfts/planes".
func webPathOf(pkgPath string) string {
	for i := 0; i < len(pkgPath); i++ {
		if pkgPath[i] == '/' {
			return pkgPath[i:]
		}
	}
	return ""
}

// imageURL returns where the image of plane id is: <image base><id>.png,
// the id on three digits, "042.png", as the image files are named. The token
// URI keeps the plain id, "42.json".
func imageURL(id int64) string {
	return imageBase + pad3(id) + ".png"
}

// pad3 writes an id of 1 to 777 on three digits: 7 -> "007", 42 -> "042".
func pad3(id int64) string {
	s := itoa(id)
	for len(s) < 3 {
		s = "0" + s
	}
	return s
}

func itoa(n int64) string {
	return strconv.FormatInt(n, 10)
}

func boolString(b bool) string {
	if b {
		return "true"
	}
	return "false"
}

package planes

import (
	"strconv"
	"strings"
)

// Render returns the state of the collection as markdown, for gnoweb:
//
//	""               the collection: minted, price, tiers, the last mints
//	"plane/<id>"     one plane: traits, owner
//	"player/<addr>"  the planes of one address
//
// Everything printed here is a row of the table, whose charset the tests
// pin, a setting validated when it was written, or an address the chain gave
// the realm. The two caller-supplied values, an id and an address, are
// printed only once parsed and found valid. Nothing needs markdown escaping.
// No images: the planes are drawn by the game and by the website.
func Render(path string) string {
	switch {
	case path == "":
		return renderHome()
	case strings.HasPrefix(path, "plane/"):
		if id, err := strconv.ParseInt(strings.TrimPrefix(path, "plane/"), 10, 64); err == nil {
			if p, ok := getPlane(id); ok {
				return renderPlane(p)
			}
		}
	case strings.HasPrefix(path, "player/"):
		if addr := address(strings.TrimPrefix(path, "player/")); validAddress(addr) {
			return renderPlayer(addr)
		}
	}
	return "# gnofly planes\n\nPage not found. Go back to the [collection](" + link("") + ").\n"
}

// link returns the gnoweb URL of a Render path of this realm.
func link(path string) string {
	if path == "" {
		return webPath
	}
	return webPath + ":" + path
}

func renderHome() string {
	var b strings.Builder
	b.WriteString("# gnofly planes\n\n")
	b.WriteString("777 planes to fly in gnofly, a multiplayer plane game. Each one is a GRC721 token with a name,\n")
	b.WriteString("a model, three colours, a tier and a laser, drawn from a table written once and for all.\n")
	b.WriteString("Mint up to 7 at once with `Mint` and count times the price attached, then pick one in the hangar of the game.\n\n")

	b.WriteString("| | |\n|---|---|\n")
	b.WriteString("| Minted | " + itoa(Minted()) + " of " + itoa(supply) + " |\n")
	b.WriteString("| Burned | " + itoa(Minted()-Token.TotalSupply()) + " |\n")
	b.WriteString("| Price | " + gnot(price) + " |\n")
	b.WriteString("| Mint open | " + yesNo(mintOpen) + " |\n")
	b.WriteString("| Per wallet | " + itoa(mintCap) + " |\n")
	b.WriteString("| Royalty | " + percent(RoyaltyBps()) + " to the treasury |\n")
	b.WriteString("| Treasury | " + roles.Treasury().String() + " |\n\n")

	b.WriteString("## Tiers\n\n")
	b.WriteString("| Tier | Planes | Minted |\n|---|---|---|\n")
	for i, tier := range strings.Split(tiers, ",") {
		b.WriteString("| " + tier + " | " + itoa(tierSupply[i]) + " | " + itoa(tierMinted[i]) + " |\n")
	}

	b.WriteString("\n## Recent mints\n\n")
	recent := 0
	for _, id := range recentIDs() {
		owner := ownerOf(id)
		if owner == "" {
			continue // burned
		}
		if recent == 0 {
			b.WriteString("| Plane | Tier | Owner |\n|---|---|---|\n")
		}
		p := mustPlane(id)
		b.WriteString("| " + planeLink(p) + " | " + p.tier + " | " + playerLink(owner) + " |\n")
		recent++
	}
	if recent == 0 {
		b.WriteString("No plane is minted yet.\n")
	}
	return b.String()
}

func renderPlane(p plane) string {
	var b strings.Builder
	b.WriteString("# " + p.name + "\n\n")
	b.WriteString("Plane " + itoa(p.id) + " of " + itoa(supply) + ", " + p.tier + ".\n\n")

	b.WriteString("| | |\n|---|---|\n")
	b.WriteString("| Model | " + p.model + " |\n")
	b.WriteString("| Pilot | " + p.pilot + " |\n")
	b.WriteString("| Body | `" + p.body + "` |\n")
	b.WriteString("| Wing | `" + p.wing + "` |\n")
	b.WriteString("| Accent | `" + p.accent + "` |\n")
	b.WriteString("| Laser | `" + p.laser + "` |\n")
	b.WriteString("| Tier | " + p.tier + " |\n")
	owner := ownerOf(p.id)
	switch {
	case owner == "" && wasMinted(p.id):
		b.WriteString("| Owner | burned |\n")
	case owner == "":
		b.WriteString("| Owner | not minted yet |\n")
	default:
		b.WriteString("| Owner | " + playerLink(owner) + " |\n")
		b.WriteString("| Metadata | `" + imageBase + itoa(p.id) + ".json` |\n")
	}
	b.WriteString("\n[Collection](" + link("") + ")\n")
	return b.String()
}

func renderPlayer(addr address) string {
	var b strings.Builder
	b.WriteString("# Pilot " + addr.String() + "\n\n")
	n, _ := Token.BalanceOf(addr)
	if n == 0 {
		b.WriteString("This address owns no plane.\n")
	} else {
		b.WriteString(itoa(n) + " plane" + plural(n) + ", minted " + itoa(mintedBy(addr)) + " of " + itoa(mintCap) + " allowed.\n\n")
		b.WriteString("| Plane | Model | Pilot | Tier |\n|---|---|---|---|\n")
		found := int64(0)
		for id := int64(1); id <= supply && found < n; id++ {
			if ownerOf(id) != addr {
				continue
			}
			p := mustPlane(id)
			b.WriteString("| " + planeLink(p) + " | " + p.model + " | " + p.pilot + " | " + p.tier + " |\n")
			found++
		}
	}
	b.WriteString("\n[Collection](" + link("") + ")\n")
	return b.String()
}

// planeLink is "[42 Storm Saint](.../plane/42)".
func planeLink(p plane) string {
	return "[" + itoa(p.id) + " " + p.name + "](" + link("plane/"+itoa(p.id)) + ")"
}

// playerLink is "[g1...](.../player/g1...)".
func playerLink(addr address) string {
	return "[" + addr.String() + "](" + link("player/"+addr.String()) + ")"
}

// gnot formats an amount of ugnot in GNOT, without trailing zeros:
// 77000000 gives "77 GNOT", 9500000 gives "9.5 GNOT".
func gnot(ugnot int64) string {
	whole, frac := ugnot/1000000, ugnot%1000000
	if frac == 0 {
		return itoa(whole) + " GNOT"
	}
	decimals := itoa(1000000 + frac)[1:] // all six of them, zeros included
	end := len(decimals)
	for decimals[end-1] == '0' {
		end--
	}
	return itoa(whole) + "." + decimals[:end] + " GNOT"
}

// percent formats basis points as a percentage, without trailing zeros:
// 500 gives "5%", 250 gives "2.5%", 1 gives "0.01%".
func percent(bps int64) string {
	whole, frac := bps/100, bps%100
	switch {
	case frac == 0:
		return itoa(whole) + "%"
	case frac%10 == 0:
		return itoa(whole) + "." + itoa(frac/10) + "%"
	case frac < 10:
		return itoa(whole) + ".0" + itoa(frac) + "%"
	}
	return itoa(whole) + "." + itoa(frac) + "%"
}

func plural(n int64) string {
	if n == 1 {
		return ""
	}
	return "s"
}

func yesNo(b bool) string {
	if b {
		return "yes"
	}
	return "no"
}

// recentIDs returns the last ids minted, newest first.
func recentIDs() []int64 {
	var ids []int64
	for _, id := range recent {
		if id != 0 {
			ids = append(ids, id)
		}
	}
	return ids
}

package planes

import "gno.land/r/g1t2kg2vtr3fukg43eujkn6x53gfdyakhngt4sfd/gnofly/game/v0"

// The planes realm keeps no roles of its own. Who administers it and where
// its money goes are the answers of the game realm, asked again at every
// call: an admin removed there is refused here in the same block, and a
// treasury moved there receives the next mint.

// authority is the set of questions this realm asks about roles.
type authority interface {
	IsAdmin(addr address) bool
	Treasury() address
}

// gameRoles answers with the roles of the game realm.
type gameRoles struct{}

func (gameRoles) IsAdmin(addr address) bool { return game.IsAdmin(addr) }
func (gameRoles) Treasury() address         { return game.Treasury() }

// roles is the authority of this realm: the game realm, always.
//
// It is a variable for one reason. Under `gno test` an imported realm is
// initialized without a deployer, and a test of this package has no way to
// become an admin of the game realm, so the tests put their own answers
// here. Nothing outside the test files assigns it, and there is no setter.
var roles authority = gameRoles{}

// callerOf returns the verified caller of a crossing function. rlm must be
// the cur of the crossing function calling this helper: a stale or forged
// realm value fails IsCurrent, and Previous is only meaningful on a live one.
//
// It takes the realm in second position on purpose, like p/nt/ownable does:
// a function whose first parameter is a realm is a crossing function.
func callerOf(_ int, rlm realm) address {
	if !rlm.IsCurrent() {
		panic(errSpoofedRealm)
	}
	return rlm.Previous().Address()
}

// assertAdmin panics unless the caller is an admin of the game realm, and
// returns the caller.
func assertAdmin(_ int, rlm realm) address {
	caller := callerOf(0, rlm)
	if !roles.IsAdmin(caller) {
		panic(errNotAdmin)
	}
	return caller
}

package planes

import (
	"strings"

	"gno.land/p/nt/grc721/v0"
)

// plane is one row of the table: what a plane looks like. Nothing here is
// stored per token, the table is the only copy.
type plane struct {
	id     int64
	name   string
	model  string // a model the client draws, see models
	pilot  string // none or gnome
	body   string // colours, "#rrggbb"; on the super-gnome: cape, suit, emblem
	wing   string
	accent string
	tier   string // common, rare, epic, legendary
	laser  string // the colour of its shots, "#rrggbb"
}

// The table is one string of 777 lines,
// "id|name|model|pilot|body|wing|accent|tier|laser",
// in id order (see table.gno). It is kept as a string and read in place
// because storage is paid per byte at deploy: 777 structs would cost about
// ten times as much as the text, and a plane is read far less often than it
// is paid for.
//
// A row is found by bisection on the offsets of the string: from any offset,
// the start of its line is at most a line's length back. Ten steps of a
// hundred bytes each, where walking the lines from the top would be forty
// thousand.

// row returns the line of plane id, or "" when there is no such row.
func row(id int64) string {
	if id < 1 || id > supply {
		return ""
	}
	lo, hi := 0, len(table)-1
	for lo <= hi {
		mid := (lo + hi) / 2
		start, end := lineAt(mid)
		n := idAt(start, end)
		switch {
		case n == id:
			return table[start:end]
		case n < id:
			lo = end + 1
		default:
			hi = start - 1
		}
	}
	return ""
}

// lineAt returns the bounds of the line containing offset i: start is its
// first byte, end the offset of its newline, or len(table) for the last line.
func lineAt(i int) (start, end int) {
	start = i
	for start > 0 && table[start-1] != '\n' {
		start--
	}
	end = i
	for end < len(table) && table[end] != '\n' {
		end++
	}
	return start, end
}

// rowID reads the id of the line containing offset i, or 0 when the line
// does not start with a number.
func rowID(i int) int64 {
	start, end := lineAt(i)
	return idAt(start, end)
}

// idAt reads the id at the start of the line table[start:end].
func idAt(start, end int) int64 {
	n := int64(0)
	for j := start; j < end; j++ {
		c := table[j]
		if c == '|' {
			return n
		}
		if c < '0' || c > '9' || j-start > 3 {
			return 0
		}
		n = n*10 + int64(c-'0')
	}
	return 0
}

// parsePlane turns a row into a plane. It checks the shape of the row, not
// its values: those are the table's promise, checked by the tests.
func parsePlane(line string) (plane, bool) {
	f := strings.Split(line, "|")
	if len(f) != 9 {
		return plane{}, false
	}
	id := int64(0)
	for i := 0; i < len(f[0]); i++ {
		id = id*10 + int64(f[0][i]-'0')
	}
	return plane{id: id, name: f[1], model: f[2], pilot: f[3], body: f[4], wing: f[5], accent: f[6], tier: f[7], laser: f[8]}, true
}

// getPlane returns plane id from the table, or false when the id is out of
// range.
func getPlane(id int64) (plane, bool) {
	line := row(id)
	if line == "" {
		return plane{}, false
	}
	p, ok := parsePlane(line)
	if !ok {
		panic(errCorruptRow)
	}
	return p, true
}

// mustPlane returns plane id from the table, or panics.
func mustPlane(id int64) plane {
	p, ok := getPlane(id)
	if !ok {
		panic(errUnknownPlane)
	}
	return p
}

// tokenID is the GRC721 id of plane id: its number, in decimal.
func tokenID(id int64) grc721.TokenID {
	return grc721.TokenID(itoa(id))
}

// valid reports whether p respects every rule of the table. The tests run it
// on all 777 rows; the realm trusts the table after that, which is what
// makes the hand-built JSON and markdown of this realm safe.
func (p plane) valid() bool {
	return p.id >= 1 && p.id <= supply &&
		validName(p.name) &&
		oneOf(p.model, models) &&
		oneOf(p.pilot, pilots) &&
		validColor(p.body) && validColor(p.wing) && validColor(p.accent) && validColor(p.laser) &&
		oneOf(p.tier, tiers)
}

// validName reports whether s matches [A-Za-z0-9 -]{1,24}.
func validName(s string) bool {
	if len(s) == 0 || len(s) > 24 {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if !(c >= 'a' && c <= 'z') && !(c >= 'A' && c <= 'Z') && !(c >= '0' && c <= '9') && c != ' ' && c != '-' {
			return false
		}
	}
	return true
}

// validColor reports whether s is "#rrggbb" with lowercase hex digits.
func validColor(s string) bool {
	if len(s) != 7 || s[0] != '#' {
		return false
	}
	for i := 1; i < len(s); i++ {
		c := s[i]
		if !(c >= '0' && c <= '9') && !(c >= 'a' && c <= 'f') {
			return false
		}
	}
	return true
}

// validBase reports whether s can be an image base: an https URL ending in
// "/", 12 to 200 characters of [A-Za-z0-9./_-:]. The charset keeps it safe
// in JSON and markdown without escaping.
func validBase(s string) bool {
	if len(s) < 12 || len(s) > 200 || !strings.HasPrefix(s, "https://") || s[len(s)-1] != '/' {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if !(c >= 'a' && c <= 'z') && !(c >= 'A' && c <= 'Z') && !(c >= '0' && c <= '9') &&
			c != '.' && c != '/' && c != '_' && c != '-' && c != ':' {
			return false
		}
	}
	return true
}

// validAddress reports whether addr is a valid address in its canonical,
// lowercase form, the only form the game realm and this one key on.
func validAddress(addr address) bool {
	return addr.IsValid() && addr[0] == 'g'
}

// oneOf reports whether s is one of the comma-separated words of list.
func oneOf(s, list string) bool {
	for _, w := range strings.Split(list, ",") {
		if s == w {
			return true
		}
	}
	return false
}

package skins

import (
	"chain"
	"chain/banker"

	// Only for OriginSend, in Buy. Caller identity always comes from
	// cur.Previous(), never from this package.
	"chain/runtime/unsafe"

	"gno.land/p/nt/grc721/v0"
)

// Buy buys one token of a skin design for the caller and returns its id. The
// exact price must be attached to the transaction (-send "<price>ugnot") and
// is forwarded to the treasury of the game realm before the call returns.
//
// An address owns at most one token of a design: a skin cannot be given
// away, so a second copy would be of no use. It must be called directly by a
// user (maketx call): a call relayed by another realm or by a maketx run
// script is refused.
func Buy(cur realm, skinID string) int64 {
	buyer := callerOf(0, cur)

	// Paid-call guard: two checks that are only correct together.
	//
	// (a) The caller is a plain user account. Only then is the -send
	//     envelope guaranteed to have landed at this realm's address.
	if !cur.Previous().IsUserCall() {
		panic(errNotUserCall)
	}
	d := getDesign(skinID)
	if d == nil {
		panic(errUnknownSkin)
	}
	if !d.listed {
		panic(errSkinUnlisted)
	}
	if d.maxSupply > 0 && d.minted >= d.maxSupply {
		panic(errSoldOut)
	}
	key := ownedKey(buyer, skinID)
	if owned.Has(key) {
		panic(errAlreadyOwned)
	}

	// (b) The envelope is exactly the price: one coin, the right denom, the
	//     right amount.
	sent := unsafe.OriginSend()
	if len(sent) != 1 || sent[0].Denom != payDenom || sent[0].Amount != d.price {
		panic("gnofly: wrong payment, send exactly " + itoa(d.price) + payDenom)
	}
	treasury := roles.Treasury()
	payment := chain.NewCoins(chain.NewCoin(payDenom, d.price))
	banker.NewBanker(banker.BankerTypeOriginSend, cur).SendCoins(cur.Address(), treasury, payment)

	id := nextID
	nextID++
	tid := grc721.TokenID(itoa(id))
	if err := ledger.Mint(buyer, tid); err != nil {
		panic(err)
	}
	tokenSkin.Set(string(tid), skinID)
	owned.Set(key, id)
	d.minted++

	chain.Emit("SkinBought",
		"id", itoa(id),
		"skin", skinID,
		"buyer", buyer.String(),
		"price", itoa(d.price),
		"treasury", treasury.String(),
	)
	return id
}

// Burn destroys a skin token. Only its owner can. The storage deposit paid at
// purchase comes back; the price does not. The owner can buy the design
// again, while it is listed.
func Burn(cur realm, id int64) {
	caller := callerOf(0, cur)
	skinID := skinOf(id)
	if skinID == "" {
		panic(errNotMinted)
	}
	if ownerOf(id) != caller {
		panic(errNotSkinOwner)
	}
	tid := grc721.TokenID(itoa(id))
	if err := ledger.Burn(tid); err != nil {
		panic(err)
	}
	tokenSkin.Remove(string(tid))
	owned.Remove(ownedKey(caller, skinID))
	chain.Emit("SkinBurned", "id", itoa(id), "skin", skinID, "owner", caller.String())
}

// ownedKey is the key of owned: the address, then the design.
func ownedKey(addr address, skinID string) string {
	return addr.String() + "/" + skinID
}

// skinOf returns the design of token id, "" when there is no such token.
func skinOf(id int64) string {
	v := tokenSkin.Get(itoa(id))
	if v == nil {
		return ""
	}
	return v.(string)
}

// ownerOf returns who owns token id, "" for none.
func ownerOf(id int64) address {
	owner, err := token.OwnerOf(grc721.TokenID(itoa(id)))
	if err != nil {
		return ""
	}
	return owner
}

package skins

// catalog is the skin catalog at deploy, one design per line, sorted by id:
//
//	id|name|model|pilot|body|wing|accent|price
//
// The rules are those of SetSkin (see validate.gno); the tests check every
// line. The website reads this file too, at build, to serve the metadata of
// each design at https://gnofly.xyz/nft/skins/<id>.json: a design added later
// with SetSkin needs a line here as well for its JSON to exist.
//
// Classic, the look every pilot flies by default, is not here: it is free and
// drawn by the client, not a token.
const catalog = `baron|Red Baron|biplane|none|#c1121f|#780000|#fdf0d5|7000000
gnome|Garden Gnome|prop|none|#2a9d8f|#e9c46a|#264653|77000000
goldie|Golden Goose|jet|none|#ffd60a|#ffc300|#000814|7777000000
stealth|Night Shift|jet|none|#22223b|#4a4e69|#f72585|777000000`

// v0 - Unaudited: This is an initial version that has not yet been formally audited.
// Use in production at your own risk.
//
// Package skins is the catalog of plane skins of gnofly, a multiplayer plane
// game, and the tokens of the skins sold. Every skin bought is a GRC721
// token on gno.land/p/nt/grc721/v0, one per buyer and design.
//
// The tokens are soulbound: there is no TransferFrom, no Approve and no
// SetApprovalForAll, and the token object is not exported, so nothing can
// move a skin away from its buyer. Its owner can Burn it, which gives back
// the storage deposit (not the price).
//
// Supply is unlimited by default; an admin can cap a design. Classic, the
// look every pilot flies by default, is free and is not a token.
//
// Writers:
//
//   - anyone buys a skin with its price attached (Buy), and burns their own
//     (Burn);
//   - the admins of the game realm edit the catalog (SetSkin, SetSkinListed).
//
// The realm keeps no roles and no money: admins and treasury are those of
// gno.land/r/g1t2kg2vtr3fukg43eujkn6x53gfdyakhngt4sfd/gnofly/game/v0, and every
// sale is forwarded to the treasury in the same transaction.
//
// A token stores only its owner (the ledger), its design and an entry in the
// buyer's list: no metadata record and no URI. TokenURI is computed from the
// design. Reads are plain functions meant for vm/qeval: CatalogJSON, SkinsOf,
// OwnerOf, SkinOf, TokenURI, Render.
package skins

package skins

import (
	"errors"
	"strings"

	"gno.land/p/nt/grc721/v0"
	"gno.land/p/onbloc/json/v0"
)

// CatalogJSON returns every design, sorted by id, as a JSON array:
//
//	[ { "id": "baron", "name": "Red Baron", "model": "biplane", "pilot": "none",
//	    "body": "#c1121f", "wing": "#780000", "accent": "#fdf0d5",
//	    "price": 1000000, "listed": true, "minted": 3, "maxSupply": 0 } ]
//
// The output has no whitespace. maxSupply 0 is unlimited. Classic, the free
// look, is not in it: the client draws it without a token.
func CatalogJSON() string {
	items := []*json.Node{}
	designs.Iterate("", "", func(_ string, v any) bool {
		d := v.(*design)
		b := json.Builder().
			WriteString("id", d.id).
			WriteString("name", d.name).
			WriteString("model", d.model).
			WriteString("pilot", d.pilot).
			WriteString("body", d.body).
			WriteString("wing", d.wing).
			WriteString("accent", d.accent).
			WriteNumber("price", float64(d.price)).
			WriteBool("listed", d.listed).
			WriteNumber("minted", float64(d.minted)).
			WriteNumber("maxSupply", float64(d.maxSupply))
		items = append(items, b.Node())
		return false
	})
	return encode(json.ArrayNode("", items))
}

// SkinsOf returns the designs addr owns a token of, sorted by id, as a JSON
// array: ["baron","goldie"]. It is [] for an address without skins.
func SkinsOf(addr address) string {
	ids := []*json.Node{}
	prefix := addr.String() + "/"
	if validAddress(addr) {
		// Keys sort as "<addr>/<design>": the designs of addr are one range,
		// "/" + 1 is "0".
		owned.Iterate(prefix, addr.String()+"0", func(key string, _ any) bool {
			ids = append(ids, json.StringNode("", strings.TrimPrefix(key, prefix)))
			return false
		})
	}
	return encode(json.ArrayNode("", ids))
}

// The read functions a wallet calls take a grc721.TokenID and return an
// error rather than panic, the way Adena calls them: OwnerOf("1") into two
// values, TokenURI("1") as the image it shows, TokenMetadata("1") as JSON
// for the traits. The errors are made on the call, not stored (errors.gno).

// OwnerOf returns who owns skin token tid, or an error when there is none.
func OwnerOf(tid grc721.TokenID) (address, error) {
	id, err := mintedID(tid)
	if err != nil {
		return "", err
	}
	return ownerOf(id), nil
}

// BalanceOf returns how many skin tokens addr owns, one per design at most.
func BalanceOf(addr address) (int64, error) {
	return token.BalanceOf(addr)
}

// TokenMetadata returns the metadata of skin token tid as JSON, the same for
// every token of a design, with the keys Adena reads:
//
//	{"name":"Red Baron","description":"A gnofly skin, a biplane. ...",
//	 "image":"https://gnofly.xyz/nft/skins/baron.png",
//	 "attributes":[{"traitType":"model","value":"biplane"}, ...]}
func TokenMetadata(tid grc721.TokenID) (string, error) {
	id, err := mintedID(tid)
	if err != nil {
		return "", err
	}
	d := getDesign(skinOf(id))
	if d == nil {
		return "", errors.New(errNotMinted)
	}
	pilot := ""
	if d.pilot == "gnome" {
		pilot = " flown by a gnome"
	}
	b := json.Builder().
		WriteString("name", d.name).
		WriteString("description", "A gnofly skin, a "+d.model+pilot+". Bound to its buyer: it cannot be transferred.").
		WriteString("image", uriBase+d.id+".png").
		WriteArray("attributes", func(ab *json.ArrayBuilder) {
			for _, t := range [][2]string{
				{"model", d.model}, {"pilot", d.pilot}, {"body", d.body}, {"wing", d.wing},
				{"accent", d.accent}, {"soulbound", "yes"},
			} {
				ab.WriteObject(func(o *json.NodeBuilder) {
					o.WriteString("traitType", t[0]).WriteString("value", t[1])
				})
			}
		})
	return encode(b.Node()), nil
}

// mintedID reads a token id, "1" and up in decimal, and checks it exists.
func mintedID(tid grc721.TokenID) (int64, error) {
	s := string(tid)
	n := int64(0)
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' || i > 15 || (i == 0 && s[i] == '0') {
			return 0, errors.New(errNotMinted)
		}
		n = n*10 + int64(s[i]-'0')
	}
	if n == 0 || ownerOf(n) == "" {
		return 0, errors.New(errNotMinted)
	}
	return n, nil
}

// SkinOf returns the design of skin token id, "" when there is no such token.
func SkinOf(id int64) string {
	return skinOf(id)
}

// TokenURI returns the image of skin token tid,
// "https://gnofly.xyz/nft/skins/<design>.png": what a wallet shows (Adena
// puts it in an <img>). The metadata is TokenMetadata, or
// "https://gnofly.xyz/nft/skins/<design>.json" on the website. It is
// computed, not stored: a token costs no URI in deposit.
func TokenURI(tid grc721.TokenID) (string, error) {
	id, err := mintedID(tid)
	if err != nil {
		return "", err
	}
	return uriBase + skinOf(id) + ".png", nil
}

// encode marshals a document built above; it cannot fail on one.
func encode(n *json.Node) string {
	out, err := json.Marshal(n)
	if err != nil {
		panic(err)
	}
	return string(out)
}

package skins

import "strings"

// Render returns the shop as markdown, for gnoweb:
//
//	""               the catalog
//	"skin/<id>"      one design
//	"player/<addr>"  the skins of one address
//
// Everything printed went through validate.gno when it was written, or is
// an address the chain gave the realm; the caller-supplied id and address are
// printed only once found valid.
func Render(path string) string {
	switch {
	case path == "":
		return renderHome()
	case strings.HasPrefix(path, "skin/"):
		if d := getDesign(strings.TrimPrefix(path, "skin/")); d != nil {
			return renderDesign(d)
		}
	case strings.HasPrefix(path, "player/"):
		if addr := address(strings.TrimPrefix(path, "player/")); validAddress(addr) {
			return renderPlayer(addr)
		}
	}
	return "# gnofly skins\n\nPage not found. Go back to the [shop](" + link("") + ").\n"
}

func link(path string) string {
	if path == "" {
		return webPath
	}
	return webPath + ":" + path
}

func renderHome() string {
	var b strings.Builder
	b.WriteString("# gnofly skins\n\n")
	b.WriteString("Paint jobs for the planes of gnofly. Each one bought is a token bound to its buyer: it cannot be\n")
	b.WriteString("transferred. Buy one with `Buy` and its price attached, then fly it from the hangar of the game.\n")
	b.WriteString("Classic is free for everyone and is not sold here.\n\n")
	b.WriteString("| Skin | Model | Price | Sold | Supply | For sale |\n|---|---|---|---|---|---|\n")
	designs.Iterate("", "", func(_ string, v any) bool {
		d := v.(*design)
		b.WriteString("| " + designLink(d) + " | " + d.model + " | " + gnot(d.price) + " | " + itoa(d.minted) +
			" | " + supplyText(d.maxSupply) + " | " + yesNo(d.listed) + " |\n")
		return false
	})
	b.WriteString("\nTreasury: " + roles.Treasury().String() + "\n")
	return b.String()
}

func renderDesign(d *design) string {
	var b strings.Builder
	b.WriteString("# " + d.name + "\n\n")
	b.WriteString("| | |\n|---|---|\n")
	b.WriteString("| Id | " + d.id + " |\n")
	b.WriteString("| Model | " + d.model + " |\n")
	b.WriteString("| Pilot | " + d.pilot + " |\n")
	b.WriteString("| Body | `" + d.body + "` |\n")
	b.WriteString("| Wing | `" + d.wing + "` |\n")
	b.WriteString("| Accent | `" + d.accent + "` |\n")
	b.WriteString("| Price | " + gnot(d.price) + " |\n")
	b.WriteString("| Sold | " + itoa(d.minted) + " of " + supplyText(d.maxSupply) + " |\n")
	b.WriteString("| For sale | " + yesNo(d.listed) + " |\n")
	b.WriteString("| Metadata | `" + uriBase + d.id + ".json` |\n")
	b.WriteString("\n[Shop](" + link("") + ")\n")
	return b.String()
}

func renderPlayer(addr address) string {
	var b strings.Builder
	b.WriteString("# Pilot " + addr.String() + "\n\n")
	n := 0
	prefix := addr.String() + "/"
	owned.Iterate(prefix, addr.String()+"0", func(key string, v any) bool {
		if n == 0 {
			b.WriteString("| Skin | Token |\n|---|---|\n")
		}
		d := getDesign(strings.TrimPrefix(key, prefix))
		if d != nil {
			b.WriteString("| " + designLink(d) + " | " + itoa(v.(int64)) + " |\n")
		}
		n++
		return false
	})
	if n == 0 {
		b.WriteString("No skin yet: this pilot flies Classic.\n")
	}
	b.WriteString("\n[Shop](" + link("") + ")\n")
	return b.String()
}

func designLink(d *design) string {
	return "[" + d.name + "](" + link("skin/"+d.id) + ")"
}

func supplyText(n int64) string {
	if n == 0 {
		return "unlimited"
	}
	return itoa(n)
}

// gnot writes ugnot as GNOT: 1000000 -> "1 GNOT", 1500000 -> "1.5 GNOT".
func gnot(ugnot int64) string {
	whole, frac := ugnot/1000000, ugnot%1000000
	if frac == 0 {
		return itoa(whole) + " GNOT"
	}
	f := itoa(frac + 1000000)[1:]
	for f[len(f)-1] == '0' {
		f = f[:len(f)-1]
	}
	return itoa(whole) + "." + f + " GNOT"
}

func yesNo(b bool) string {
	if b {
		return "yes"
	}
	return "no"
}

package skins

import "gno.land/r/g1t2kg2vtr3fukg43eujkn6x53gfdyakhngt4sfd/gnofly/game/v0"

// The skins realm keeps no roles of its own. Who administers it and where
// its money goes are the answers of the game realm, asked again at every
// call: an admin removed there is refused here in the same block, and a
// treasury moved there receives the next sale.

// authority is the set of questions this realm asks about roles.
type authority interface {
	IsAdmin(addr address) bool
	Treasury() address
}

// gameRoles answers with the roles of the game realm.
type gameRoles struct{}

func (gameRoles) IsAdmin(addr address) bool { return game.IsAdmin(addr) }
func (gameRoles) Treasury() address         { return game.Treasury() }

// roles is the authority of this realm: the game realm, always.
//
// It is a variable for one reason. Under `gno test` an imported realm is
// initialized without a deployer, and a test of this package has no way to
// become an admin of the game realm, so the tests put their own answers
// here. Nothing outside the test files assigns it, and there is no setter.
var roles authority = gameRoles{}

// callerOf returns the verified caller of a crossing function. rlm must be
// the cur of the crossing function calling this helper: a stale or forged
// realm value fails IsCurrent, and Previous is only meaningful on a live one.
//
// It takes the realm in second position on purpose, like p/nt/ownable does:
// a function whose first parameter is a realm is a crossing function.
func callerOf(_ int, rlm realm) address {
	if !rlm.IsCurrent() {
		panic(errSpoofedRealm)
	}
	return rlm.Previous().Address()
}

// assertAdmin panics unless the caller is an admin of the game realm, and
// returns the caller.
func assertAdmin(_ int, rlm realm) address {
	caller := callerOf(0, rlm)
	if !roles.IsAdmin(caller) {
		panic(errNotAdmin)
	}
	return caller
}

package skins

import (
	"chain"
	"strconv"
	"strings"

	"gno.land/p/nt/bptree/v0"
	"gno.land/p/nt/grc721/v0"
)

// design is one skin of the catalog: what it looks like and how it sells.
type design struct {
	id        string
	name      string
	model     string // a model the client draws (web/src/world/planes.ts)
	pilot     string // none or gnome
	body      string // colours, "#rrggbb"
	wing      string
	accent    string
	price     int64 // ugnot
	maxSupply int64 // how many tokens of it can ever be minted, 0 for no limit
	minted    int64 // tokens minted so far, burned ones included
	listed    bool  // an unlisted design cannot be bought, owners keep theirs
}

// The state. Nothing is exported by reference: the ledger and the trees are
// /p/ types with mutator methods. The token itself is not exported either:
// its tellers move tokens, and a skin never moves (soulbound, see doc.gno).
var (
	token  *grc721.Token
	ledger *grc721.PrivateLedger

	designs bptree.BPTree // design id -> *design

	// Per token, as little as possible: the skins are bought for a few GNOT
	// and every byte is a deposit. The ledger keeps the owner; tokenSkin the
	// design, as a string; owned answers "does addr own design x" and lists
	// the designs of addr, keyed "<addr>/<design>", value the token id.
	tokenSkin bptree.BPTree // token id -> design id
	owned     bptree.BPTree // "<addr>/<design>" -> token id

	nextID int64 // the id of the next token, 1 first

	webPath string // "/r/.../gnofly/nfts/skins", for the links of Render
)

const (
	tokenName   = "gnofly skins"
	tokenSymbol = "SKIN"
	payDenom    = "ugnot"
	maxPrice    = int64(1000000000000)

	// uriBase is where the website serves the metadata of each design: a
	// token's URI is <uriBase><design>.json. It is computed on read, not
	// stored per token.
	uriBase = "https://gnofly.xyz/nft/skins/"

	classic = "classic" // the free look, never a token
)

func init(cur realm) {
	bootstrap(0, cur)
}

// bootstrap (re)creates the state and seeds the catalog. The tests call it to
// start over.
func bootstrap(_ int, rlm realm) {
	token, ledger = grc721.NewToken(tokenName, tokenSymbol, 0, rlm)
	designs = bptree.BPTree{}
	tokenSkin = bptree.BPTree{}
	owned = bptree.BPTree{}
	nextID = 1
	webPath = webPathOf(rlm.PkgPath())
	for _, line := range strings.Split(catalog, "\n") {
		f := strings.Split(line, "|")
		if len(f) != 8 {
			panic(errBadCatalog)
		}
		price, err := strconv.ParseInt(f[7], 10, 64)
		if err != nil {
			panic(errBadCatalog)
		}
		putDesign(f[0], f[1], f[2], f[3], f[4], f[5], f[6], price, 0)
	}
}

// getDesign returns the design registered under id, or nil.
func getDesign(id string) *design {
	v := designs.Get(id)
	if v == nil {
		return nil
	}
	return v.(*design)
}

// putDesign validates and stores a design. An existing one keeps its count
// and its listed flag; a new one starts listed.
func putDesign(id, name, model, pilot, body, wing, accent string, price, maxSupply int64) {
	if !validID(id) {
		panic(errInvalidID)
	}
	if id == classic {
		panic(errReservedID)
	}
	if !validName(name) {
		panic(errInvalidName)
	}
	if !validModel(model) {
		panic(errInvalidModel)
	}
	if pilot != "none" && pilot != "gnome" {
		panic(errInvalidPilot)
	}
	if !validColor(body) || !validColor(wing) || !validColor(accent) {
		panic(errInvalidColor)
	}
	if price < 1 || price > maxPrice {
		panic(errInvalidPrice)
	}
	if maxSupply < 0 {
		panic(errInvalidSupply)
	}
	d := &design{id: id, listed: true}
	if old := getDesign(id); old != nil {
		d.minted, d.listed = old.minted, old.listed
	}
	d.name, d.model, d.pilot = name, model, pilot
	d.body, d.wing, d.accent = body, wing, accent
	d.price, d.maxSupply = price, maxSupply
	designs.Set(id, d)
}

// SetSkin creates or updates a design. Admin only.
//
// id is [a-z0-9-]{1,32} and not "classic", name [A-Za-z0-9 '.!-]{1,40}, model
// [a-z0-9-]{1,16}, pilot none or gnome, colours "#rrggbb" in lowercase, price
// 1 to 1e12 ugnot, maxSupply 0 for unlimited. A max supply under what is
// already minted stops the sales, it takes nothing back. Owners keep their
// tokens whatever happens to the design; its look is read from here, so a
// change of colours repaints every copy.
func SetSkin(cur realm, id, name, model, pilot, body, wing, accent string, price, maxSupply int64) {
	assertAdmin(0, cur)
	putDesign(id, name, model, pilot, body, wing, accent, price, maxSupply)
	chain.Emit("SkinSet", "id", id, "price", itoa(price), "maxSupply", itoa(maxSupply))
}

// SetSkinListed puts a design on or off sale. Admin only.
func SetSkinListed(cur realm, id string, listed bool) {
	assertAdmin(0, cur)
	d := getDesign(id)
	if d == nil {
		panic(errUnknownSkin)
	}
	d.listed = listed
	chain.Emit("SkinListed", "id", id, "listed", boolString(listed))
}

// webPathOf turns "gno.land/r/..." into "/r/...".
func webPathOf(pkgPath string) string {
	for i := 0; i < len(pkgPath); i++ {
		if pkgPath[i] == '/' {
			return pkgPath[i:]
		}
	}
	return ""
}

func itoa(n int64) string {
	return strconv.FormatInt(n, 10)
}

func boolString(b bool) string {
	if b {
		return "true"
	}
	return "false"
}

package skins

// The string rules below are what makes the hand-built JSON and the markdown
// of this realm safe: every string that is stored and later printed went
// through one of them, and none of them lets a quote, a backslash, a pipe, a
// bracket or a control character in.

const (
	maxIDLen    = 32
	maxModelLen = 16
	maxNameLen  = 40
)

// validID reports whether s matches [a-z0-9-]{1,32}.
func validID(s string) bool {
	return isSlug(s, maxIDLen)
}

// validModel reports whether s matches [a-z0-9-]{1,16}.
func validModel(s string) bool {
	return isSlug(s, maxModelLen)
}

// validName reports whether s matches [A-Za-z0-9 '.!-]{1,40}. The charset is
// deliberately narrow so that a name can be embedded in JSON and markdown
// without escaping.
func validName(s string) bool {
	if len(s) == 0 || len(s) > maxNameLen {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch {
		case c >= 'a' && c <= 'z', c >= 'A' && c <= 'Z', c >= '0' && c <= '9':
		case c == ' ', c == '\'', c == '.', c == '!', c == '-':
		default:
			return false
		}
	}
	return true
}

// validColor reports whether s is "#rrggbb" with lowercase hex digits.
func validColor(s string) bool {
	if len(s) != 7 || s[0] != '#' {
		return false
	}
	for i := 1; i < len(s); i++ {
		c := s[i]
		if !(c >= '0' && c <= '9') && !(c >= 'a' && c <= 'f') {
			return false
		}
	}
	return true
}

// validAddress reports whether addr is a valid address in its canonical,
// lowercase form.
//
// Bech32 can also be written in all capitals, and address.IsValid accepts
// that. To this realm the capitals would be a second key for the same
// account: a second player record, a second line on a leaderboard, an admin
// who can never be matched to a caller. Bech32 does not allow mixing cases,
// so looking at the first character is enough.
func validAddress(addr address) bool {
	return addr.IsValid() && addr[0] == 'g'
}

// isSlug reports whether s is 1 to max characters of [a-z0-9-].
func isSlug(s string, max int) bool {
	if len(s) == 0 || len(s) > max {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if !(c >= 'a' && c <= 'z') && !(c >= '0' && c <= '9') && c != '-' {
			return false
		}
	}
	return true
}
